        "$UFW_APP_PROFILE" \
        "$MAINTENANCE_CRON" \
        "$BACKUP_CRON" \
        "/etc/cron.d/gnss-caster-cert-renew" \
        "/etc/logrotate.d/gnss-caster" \
        "$SUDOERS_FILE" \
        "$POLKIT_RULE" \
        "$PRIVILEGED_HELPER" \
        "$BASE/main.py" \
        "$BASE/requirements.txt" \
        "$BASE/sqlite-functions.sh" \
        "$BASE/backup.sh" \
        "$BASE/restore.sh" \
        "$BASE/monitor.sh" \
        "$BASE/watchdog.sh" \
        "$BASE/update.sh" \
        "$BASE/release-update.py" \
        "$BASE/maintenance-broker.py" \
        "$BASE/backup-format.py" \
        "$BASE/diagnose.sh" \
        "$BASE/status.sh" \
        "$BASE/repair.sh" \
        "$BASE/gnss-caster-installer.sh" \
        "$APP" \
        "$VENV" \
        "$INST/config.yaml" \
        "$INST/config.py" \
        "$INST/db.sqlite" \
        "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" \
        "$BOOTSTRAP_ADMIN_PASSWORD_FILE" \
        "$SECRET_DIR" \
        "$LEGACY_SECRET_KEY_ENV_FILE" \
        "$SELF_SIGNED_CERT" \
        "$SELF_SIGNED_KEY"
    local legacy_backup
    for legacy_backup in "$INST"/secret.env.bak-*; do
        [ -e "$legacy_backup" ] || [ -L "$legacy_backup" ] || continue
        printf '%s\n' "$legacy_backup"
    done
    if [ "$SCRIPT_MODE" = repair ]; then
        printf '%s\n' /etc/ufw/user.rules /etc/ufw/user6.rules
    fi
}

record_install_journal() {
    [ -n "$ROLLBACK_DIR" ] && [ -f "$ROLLBACK_DIR/transaction.json" ] || return 0
    python3 -I /var/lib/gnss-caster-maintenance/recovery.py mark "$ROLLBACK_DIR" "$1"
}

record_maintenance_phase() {
    echo "GNSS maintenance stage: $1"
    record_install_journal "$1"
}

prepare_install_recovery() {
    # The saved program is root-only and hashed before the service is stopped.
    # Freeze the allowlist rather than recomputing it from partly changed files.
    (umask 077
        print_install_rollback_paths > "$ROLLBACK_DIR/paths.list" || exit 1
        {
            printf '%s\n' '#!/bin/bash' 'set -eE'
            declare -p SCRIPT_MODE ROLLBACK_DIR INST SERVICE \
                INSTALL_CASTER_WAS_ACTIVE INSTALL_NGINX_WAS_ACTIVE \
                INSTALL_BROKER_WAS_ACTIVE \
                INSTALL_CASTER_ENABLED INSTALL_HEALTH_WAS_OK INSTALL_HEALTH_URL || exit 1
            printf 'REPAIR_UFW_WAS_ACTIVE=%s\n' "${REPAIR_UFW_WAS_ACTIVE:-0}"
            printf '%s\n' 'ROLLBACK_ACTIVE=1'
            declare -f sqlite_database_tool rollback_backup_path \
                record_install_journal record_maintenance_phase \
                restore_install_service_state validate_install_rollback_snapshot \
                restore_install_rollback_snapshot || exit 1
            printf '%s\n' 'print_install_rollback_paths() { cat "$ROLLBACK_DIR/paths.list"; }'
            printf '%s\n' 'case "${1:-}" in' \
                '  --restore) restore_install_rollback_snapshot;;' \
                '  --services-only) restore_install_service_state;;' \
                '  *) exit 2;;' 'esac'
        } > "$ROLLBACK_DIR/recover.sh" || exit 1
        python3 -I - "$ROLLBACK_DIR/service-state.json" "$INSTALL_CASTER_WAS_ACTIVE" \
            "$INSTALL_NGINX_WAS_ACTIVE" "$INSTALL_CASTER_ENABLED" \
            "$INSTALL_HEALTH_WAS_OK" "$INSTALL_HEALTH_URL" "${REPAIR_UFW_WAS_ACTIVE:-0}" \
            "$INSTALL_BROKER_WAS_ACTIVE" << 'PY_RECOVERY_SERVICES'
import json
import sys
from pathlib import Path
keys = ('caster_active', 'nginx_active', 'caster_enabled', 'health_was_ok', 'health_url', 'ufw_active', 'broker_active')
Path(sys.argv[1]).write_text(json.dumps(dict(zip(keys, sys.argv[2:]))), encoding='utf-8')
PY_RECOVERY_SERVICES
    ) || return 1
    bash -n "$ROLLBACK_DIR/recover.sh" || return 1
    python3 -I /var/lib/gnss-caster-maintenance/recovery.py begin \
        "$ROLLBACK_DIR" "$SCRIPT_MODE" "$CASTER_VERSION" "$BASHPID"
}

create_install_rollback_snapshot() {
    local ts
    local path
    local existing_state_found=0

    systemctl is-active --quiet gnss-caster && INSTALL_CASTER_WAS_ACTIVE=1 || INSTALL_CASTER_WAS_ACTIVE=0
    systemctl is-active --quiet nginx && INSTALL_NGINX_WAS_ACTIVE=1 || INSTALL_NGINX_WAS_ACTIVE=0
    systemctl is-active --quiet gnss-caster-maintenance.socket && INSTALL_BROKER_WAS_ACTIVE=1 || INSTALL_BROKER_WAS_ACTIVE=0
    INSTALL_CASTER_ENABLED=$(systemctl is-enabled gnss-caster 2>/dev/null || true)
    INSTALL_CASTER_ENABLED="${INSTALL_CASTER_ENABLED:-not-found}"
    INSTALL_STATE_CAPTURED=1
    if [ "$INSTALL_CASTER_WAS_ACTIVE" -eq 1 ]; then
        INSTALL_HEALTH_URL="http://127.0.0.1:$(get_config_value web_port 8080)/api/health"
        curl -fsS --max-time 3 "$INSTALL_HEALTH_URL" >/dev/null 2>&1 && INSTALL_HEALTH_WAS_OK=1 || INSTALL_HEALTH_WAS_OK=0
    fi

    # Treat installation as "existing" only when core runtime/config artifacts
    # are present. An empty /opt/gnss-caster directory alone should not trigger
    # rollback snapshot creation during a clean install.
    for path in \
        "$SERVICE" \
        "$NGINX_AVAILABLE" \
        "$APP" \
        "$VENV" \
        "$INST/config.yaml" \
        "$INST/db.sqlite" \
        "$PRIVILEGED_HELPER" \
        "$SUDOERS_FILE" \
        "$POLKIT_RULE"; do
        if [ -e "$path" ] || [ -L "$path" ]; then
            existing_state_found=1
            break
        fi
    done

    if [ "$existing_state_found" -ne 1 ]; then
        # Even a clean installation must not copy files while a stray service runs.
        systemctl stop gnss-caster 2>/dev/null || true
        if systemctl is-active --quiet gnss-caster; then return 1; fi
        ROLLBACK_DIR=""
        ROLLBACK_ACTIVE=0
        echo "Clean install detected; no existing GNSS Caster state to snapshot."
        return 0
    fi

    ts=$(date +%Y%m%d_%H%M%S)
    mkdir -p "$ROLLBACK_ROOT" || return 1
    chown root:root "$ROLLBACK_ROOT" || return 1
    chmod 700 "$ROLLBACK_ROOT" || return 1
    ROLLBACK_DIR=$(mktemp -d "$ROLLBACK_ROOT/rollback-$ts-XXXXXX") || return 1
    : > "$ROLLBACK_DIR/existed.list"
    : > "$ROLLBACK_DIR/missing.list"
    mkdir -p "$ROLLBACK_DIR/files"
    prepare_install_recovery || return 1

    # Persist original service state before stopping a writer. During this
    # phase recovery only resumes services: live files have not been changed.
    if [ "$INSTALL_CASTER_WAS_ACTIVE" -eq 1 ]; then
        systemctl stop gnss-caster || return 1
    fi
    if systemctl is-active --quiet gnss-caster; then
        echo "ERROR: GNSS Caster is still running; refusing to snapshot." >&2
        return 1
    fi

    while IFS= read -r path; do
        [ -n "$path" ] || continue
        backup_path_for_rollback "$path" || return 1
    done << EOF
$(print_install_rollback_paths)
EOF

    python3 -I /var/lib/gnss-caster-maintenance/recovery.py ready "$ROLLBACK_DIR" || return 1
    ROLLBACK_ACTIVE=1
    echo "Rollback snapshot created: $ROLLBACK_DIR"
}

restore_install_service_state() {
    local failed=0
    local attempt
    record_install_journal resuming || return 1
    # Repair updates UFW application rules as well as its profile file.
    if [ "$SCRIPT_MODE" = repair ] && [ "${REPAIR_UFW_WAS_ACTIVE:-0}" -eq 1 ]; then
        ufw reload || return 1
    fi
    case "$INSTALL_CASTER_ENABLED" in
        enabled) systemctl enable gnss-caster >/dev/null 2>&1 || failed=1 ;;
        enabled-runtime) systemctl enable --runtime gnss-caster >/dev/null 2>&1 || failed=1 ;;
        disabled|not-found)
            if [ -f "$SERVICE" ]; then
                systemctl disable gnss-caster >/dev/null 2>&1 || failed=1
            fi
            ;;
    esac
    if [ "$INSTALL_NGINX_WAS_ACTIVE" -eq 1 ]; then
        if nginx -t; then
            if systemctl is-active --quiet nginx; then
                systemctl reload nginx || failed=1
            else
                systemctl start nginx || failed=1
            fi
        else
            failed=1
        fi
    elif systemctl is-active --quiet nginx; then
        systemctl stop nginx || failed=1
    fi
    if [ "${INSTALL_BROKER_WAS_ACTIVE:-0}" -eq 1 ]; then
        systemctl start gnss-caster-maintenance.socket || failed=1
    elif [ "$INSTALL_CASTER_WAS_ACTIVE" -ne 1 ] && systemctl is-active --quiet gnss-caster-maintenance.socket; then
        systemctl stop gnss-caster-maintenance.socket || failed=1
    fi
    if [ "$INSTALL_CASTER_WAS_ACTIVE" -eq 1 ]; then
        systemctl start gnss-caster || return 1
        systemctl is-active --quiet gnss-caster || return 1
        if [ "$INSTALL_HEALTH_WAS_OK" -eq 1 ]; then
            for attempt in {1..10}; do
                if curl -fsS --max-time 3 "$INSTALL_HEALTH_URL" >/dev/null 2>&1; then
                    return "$failed"
                fi
                sleep 1
            done
            echo "ERROR: Restored caster did not recover its previous web health." >&2
            return 1
        fi
    elif systemctl is-active --quiet gnss-caster; then
        systemctl stop gnss-caster || failed=1
    fi
    return "$failed"
}

validate_install_rollback_snapshot() {
    local source_path backup_path expected_path allowed
    [ -f "$ROLLBACK_DIR/existed.list" ] && [ -f "$ROLLBACK_DIR/missing.list" ] || return 1
    while IFS= read -r source_path; do
        allowed=0
        while IFS= read -r expected_path; do
            [ "$source_path" = "$expected_path" ] && allowed=1
        done < <(print_install_rollback_paths)
        [ "$allowed" -eq 1 ] || return 1
    done < <(cat "$ROLLBACK_DIR/existed.list" "$ROLLBACK_DIR/missing.list")
    while IFS= read -r source_path; do
        if grep -Fxq -- "$source_path" "$ROLLBACK_DIR/existed.list"; then
            if grep -Fxq -- "$source_path" "$ROLLBACK_DIR/missing.list"; then return 1; fi
            backup_path=$(rollback_backup_path "$source_path")
            [ -e "$backup_path" ] || [ -L "$backup_path" ] || return 1
            if [ "$source_path" = "$INST/db.sqlite" ]; then
                sqlite_database_tool check "$backup_path" || return 1
            fi
        else
            grep -Fxq -- "$source_path" "$ROLLBACK_DIR/missing.list" || return 1
        fi
    done < <(print_install_rollback_paths)
}

restore_install_rollback_snapshot() {
    record_maintenance_phase rollback
    local source_path backup_path
    local failed=0
    [ "$ROLLBACK_ACTIVE" -eq 1 ] && [ -d "$ROLLBACK_DIR" ] || return 1
    if ! systemctl stop gnss-caster; then
        if systemctl is-active --quiet gnss-caster; then return 1; fi
    fi
    if systemctl is-active --quiet gnss-caster; then return 1; fi
    if systemctl is-active --quiet gnss-caster-maintenance.socket; then
        systemctl stop gnss-caster-maintenance.socket || return 1
    fi
    # Validate every snapshot component before deleting any live file.
    if ! validate_install_rollback_snapshot; then
        echo "ERROR: Rollback snapshot is incomplete or invalid: $ROLLBACK_DIR" >&2
        return 1
    fi
    echo "Restoring GNSS Caster from $ROLLBACK_DIR"
    while IFS= read -r source_path; do
        if [ "$source_path" = "$INST/db.sqlite" ]; then
            rm -f -- "$source_path-wal" "$source_path-shm" "$source_path-journal" || failed=1
        fi
        rm -rf -- "$source_path" || failed=1
    done < "$ROLLBACK_DIR/missing.list"
    while IFS= read -r source_path; do
        backup_path=$(rollback_backup_path "$source_path")
        if ! mkdir -p "$(dirname "$source_path")"; then failed=1; continue; fi
        if [ "$source_path" = "$INST/db.sqlite" ]; then
            sqlite_database_tool restore "$backup_path" "$source_path" || failed=1
        elif rm -rf -- "$source_path"; then
            cp -a "$backup_path" "$source_path" || failed=1
        else
            failed=1
        fi
    done < "$ROLLBACK_DIR/existed.list"
    if [ "$failed" -ne 0 ]; then
        echo "ERROR: File rollback was incomplete; caster remains stopped. Snapshot: $ROLLBACK_DIR" >&2
        return 1
    fi
    systemctl daemon-reload || return 1
    restore_install_service_state || return 1
    ROLLBACK_ACTIVE=0
    record_install_journal rolled_back || return 1
    echo "Rollback completed; previous service state restored."
}

handle_install_exit() {
    local exit_code=$?
    # ERR is inherited by command substitutions; only the main shell restores.
    [ "$BASHPID" = "$INSTALL_OWNER_BASHPID" ] || return "$exit_code"
    trap - EXIT ERR
    trap '' INT TERM HUP
    set +e
    if { [ "$SCRIPT_MODE" = "install" ] || [ "$SCRIPT_MODE" = "repair" ]; } && [ "$INSTALL_COMMITTED" -ne 1 ] && [ "$INSTALL_STATE_CAPTURED" -eq 1 ]; then
        [ "$exit_code" -ne 0 ] || exit_code=1
        echo "ERROR: $SCRIPT_MODE did not complete (near line $INSTALL_FAILED_LINE)."
        if [ "$ROLLBACK_ACTIVE" -eq 1 ]; then
            if ! restore_install_rollback_snapshot; then
                record_install_journal rollback_failed || true
                echo "ERROR: Automatic rollback failed. Inspect snapshot: $ROLLBACK_DIR" >&2
            fi
        else
            # No installation files have been changed during a failed snapshot.
            # On a clean install, there is no previous runtime to restore.
            if ! restore_install_service_state; then
                record_install_journal rollback_failed || true
                echo "ERROR: Could not restore the previous service state." >&2
            else
                record_install_journal snapshot_failed || true
            fi
        fi
        [ -z "$ROLLBACK_DIR" ] || echo "Snapshot retained: $ROLLBACK_DIR"
    fi
    exit "$exit_code"
}

begin_runtime_transaction() {
    acquire_admission_guard || return 1
    write_recovery_support || return 1
    python3 -I /var/lib/gnss-caster-maintenance/recovery.py preflight || return 1
    echo "GNSS maintenance stage: snapshot"
    if [ "$SCRIPT_MODE" = repair ] && command -v ufw >/dev/null 2>&1; then
        local firewall_status
        firewall_status=$(ufw status) || return 1
        REPAIR_UFW_WAS_ACTIVE=0
        if printf '%s\n' "$firewall_status" | grep -qi '^Status: active'; then
            REPAIR_UFW_WAS_ACTIVE=1
        fi
    fi
    INSTALL_OWNER_BASHPID=$BASHPID
    trap handle_install_exit EXIT
    trap 'INSTALL_FAILED_LINE=$LINENO' ERR
    trap 'INSTALL_FAILED_LINE=$LINENO; exit 130' INT
    trap 'INSTALL_FAILED_LINE=$LINENO; exit 143' TERM
    trap 'INSTALL_FAILED_LINE=$LINENO; exit 129' HUP
    create_install_rollback_snapshot
}

finish_repair_transaction() {
    record_maintenance_phase health
    if ! run_install_smoke_tests; then
        echo "ERROR: Post-repair health gate failed; rolling back." >&2
        return 1
    fi
    # Repair temporarily starts the service to validate it, then preserves
    # the original activity and enablement settings (including nginx).
    restore_install_service_state || return 1
    record_install_journal committed || return 1
    INSTALL_COMMITTED=1
    ROLLBACK_ACTIVE=0
    trap - ERR INT TERM HUP
    # Legacy secret cleanup must follow commit: deleting these paths earlier
    # would change the manifest used by snapshot validation.
    manage_secret_files cleanup
}

validate_tls_config() {
    case "$TLS_MODE" in
        none|selfsigned|letsencrypt|existing)
            ;;
        *)
            echo "ERROR: Unsupported TLS_MODE='$TLS_MODE'"
            echo "Use one of: none, selfsigned, letsencrypt, existing"
            exit 1
            ;;
    esac

    if [ "$TLS_MODE" = "letsencrypt" ]; then
        if [ -z "$TLS_DOMAIN" ] || [ -z "$TLS_EMAIL" ]; then
            echo "ERROR: TLS_MODE=letsencrypt requires TLS_DOMAIN and TLS_EMAIL"
            echo "Example:"
            echo "  TLS_MODE=letsencrypt TLS_DOMAIN=example.com TLS_EMAIL=admin@example.com ./$SCRIPT_NAME"
            exit 1
        fi
        if ! [[ "$TLS_EMAIL" =~ ^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$ ]]; then
            echo "ERROR: TLS_EMAIL '$TLS_EMAIL' is not a valid email address."
            exit 1
        fi
    fi

    if [ "$TLS_MODE" = "existing" ]; then
        if [ -z "$TLS_CERT_FILE" ] || [ -z "$TLS_KEY_FILE" ]; then
            echo "ERROR: TLS_MODE=existing requires TLS_CERT_FILE and TLS_KEY_FILE"
            echo "Example:"
            echo "  TLS_MODE=existing TLS_CERT_FILE=/etc/ssl/mycert/fullchain.pem TLS_KEY_FILE=/etc/ssl/mycert/privkey.pem ./$SCRIPT_NAME"
            exit 1
        fi
        if [ ! -r "$TLS_CERT_FILE" ]; then
            echo "ERROR: certificate file not found or not readable: $TLS_CERT_FILE"
            exit 1
        fi
        if [ ! -r "$TLS_KEY_FILE" ]; then
            echo "ERROR: private key file not found or not readable: $TLS_KEY_FILE"
            exit 1
        fi
        if ! openssl x509 -in "$TLS_CERT_FILE" -noout >/dev/null 2>&1; then
            echo "ERROR: $TLS_CERT_FILE is not a valid PEM X.509 certificate"
            exit 1
        fi
        if ! openssl pkey -in "$TLS_KEY_FILE" -noout >/dev/null 2>&1; then
            echo "ERROR: $TLS_KEY_FILE is not a valid PEM private key"
            exit 1
        fi
        # Confirm the key actually matches the certificate by comparing public
        # keys (works for both RSA and EC, unlike a modulus-only check).
        local _cert_pub _key_pub
        _cert_pub=$(openssl x509 -in "$TLS_CERT_FILE" -noout -pubkey 2>/dev/null)
        _key_pub=$(openssl pkey -in "$TLS_KEY_FILE" -pubout 2>/dev/null)
        if [ -z "$_cert_pub" ] || [ "$_cert_pub" != "$_key_pub" ]; then
            echo "ERROR: the private key does not match the certificate"
            echo "  cert: $TLS_CERT_FILE"
            echo "  key : $TLS_KEY_FILE"
            exit 1
        fi
        # Non-fatal expiry warning: nginx will still start, but clients will
        # reject an expired certificate.
        if ! openssl x509 -in "$TLS_CERT_FILE" -checkend 0 >/dev/null 2>&1; then
            echo "WARNING: certificate $TLS_CERT_FILE is expired or unreadable dates; proceeding anyway."
        fi
    fi

    if [ -n "$TLS_DOMAIN" ]; then
        # TLS_DOMAIN reaches nginx "server_name", the certbot "-d" argument, the
        # self-signed cert CN, and the /etc/letsencrypt/live/<domain> path.
        # Restrict it to hostname characters so a crafted value cannot inject
        # nginx directives (";", newlines, "{}"), certbot flags (leading "-"),
        # extra subject-DN fields ("/"), or traverse paths.
        if ! [[ "$TLS_DOMAIN" =~ ^[A-Za-z0-9]([A-Za-z0-9.-]{0,253})$ ]]; then
            echo "ERROR: TLS_DOMAIN '$TLS_DOMAIN' is not a valid hostname."
            echo "Use letters, digits, dots and hyphens only, starting with a letter or digit (e.g. caster.example.com)."
            exit 1
        fi
        NGINX_SERVER_NAME="$TLS_DOMAIN"
    fi
}

validate_tcp_port() {
    local port_label="$1"
    local port_value="$2"

    case "$port_value" in
        ''|*[!0-9]*)
            echo "ERROR: $port_label must be a numeric TCP port, got '$port_value'"
            exit 1
            ;;
    esac

    if [ "$port_value" -lt 1 ] || [ "$port_value" -gt 65535 ]; then
        echo "ERROR: $port_label must be between 1 and 65535, got '$port_value'"
        exit 1
    fi
}

validate_install_ports() {
    validate_tcp_port "WEB_PORT" "$INSTALL_WEB_PORT"
    validate_tcp_port "NTRIP_PORT" "$INSTALL_NTRIP_PORT"

    # The application runs as an unprivileged service account and the unit
    # grants no CAP_NET_BIND_SERVICE, so it cannot bind ports below 1024 - the
    # process would die with "PermissionError: [Errno 13]" on startup. Public
    # HTTP/HTTPS is served by nginx on 80/443, which proxies to WEB_PORT.
    for _port_check in "WEB_PORT:$INSTALL_WEB_PORT" "NTRIP_PORT:$INSTALL_NTRIP_PORT"; do
        _port_label="${_port_check%%:*}"
        _port_number="${_port_check##*:}"
        if [ "$_port_number" -lt 1024 ]; then
            echo "ERROR: $_port_label must be 1024 or higher, got '$_port_number'."
            echo "  The caster runs unprivileged and cannot bind privileged ports."
            if [ "$_port_label" = "WEB_PORT" ]; then
                echo "  This is the internal backend port behind nginx - not the public one."
                echo "  nginx already serves 80/443; keep the backend on e.g. 8080 and"
                echo "  enable HTTPS with TLS_MODE instead."
            fi
            exit 1
        fi
    done

    if [ "$INSTALL_WEB_PORT" -eq "$INSTALL_NTRIP_PORT" ]; then
        echo "ERROR: WEB_PORT and NTRIP_PORT must be different"
        exit 1
    fi
}

validate_python_version() {
    local python_version

    if ! command -v python3 >/dev/null 2>&1; then
        return 1
    fi

    if ! python3 - <<'PYTHON_VERSION_CHECK'
import sys
raise SystemExit(0 if sys.version_info >= (3, 11) else 1)
PYTHON_VERSION_CHECK
    then
        python_version=$(python3 -c 'import sys; print(".".join(map(str, sys.version_info[:3])))' 2>/dev/null || echo unknown)
        echo "ERROR: Python 3.11 or newer is required; found Python ${python_version}." >&2
        return 1
    fi

    return 0
}

run_preflight_checks() {
    local free_kb
    local free_mb
    local os_name="unknown"
    local os_id="unknown"

    echo "Running pre-flight checks..."

    if ! command -v apt >/dev/null 2>&1; then
        echo "ERROR: apt is required. This installer targets Debian/Raspberry Pi OS/Ubuntu systems."
        exit 1
    fi

    if ! command -v systemctl >/dev/null 2>&1; then
        echo "ERROR: systemctl is required. This installer expects a systemd-based system."
        exit 1
    fi

    if command -v python3 >/dev/null 2>&1; then
        validate_python_version || exit 1
    else
        echo "Python 3 is not installed yet; the installer will install it and verify Python >= 3.11 afterward."
    fi

    if [ ! -d /run/systemd/system ]; then
        echo "ERROR: systemd does not appear to be PID 1 on this system."
        exit 1
    fi

    free_kb=$(df -Pk / 2>/dev/null | awk 'NR==2 {print $4}')
    case "$free_kb" in
        ''|*[!0-9]*)
            free_kb=0
            ;;
    esac
    free_mb=$((free_kb / 1024))
    if [ "$free_mb" -lt 1024 ]; then
        echo "ERROR: At least 1024 MB free disk space is required on /. Found: ${free_mb} MB"
        exit 1
    fi

    if [ -r /etc/os-release ]; then
        os_name=$(awk -F= '$1=="PRETTY_NAME" {gsub(/^"|"$/, "", $2); print $2}' /etc/os-release)
        os_id=$(awk -F= '$1=="ID" {gsub(/^"|"$/, "", $2); print $2}' /etc/os-release)
    fi

    case "$os_id" in
        debian|raspbian|ubuntu)
            echo "OS check: ${os_name:-$os_id}"
            ;;
        *)
            echo "WARNING: Untested OS '${os_name:-$os_id}'. Supported targets are Debian, Raspberry Pi OS, and Ubuntu."
            ;;
    esac

    for path in /opt /etc /var/log; do
        if [ ! -d "$path" ] || [ ! -w "$path" ]; then
            echo "ERROR: Required writable directory is not available: $path"
            exit 1
        fi
    done

    if [ "$TLS_MODE" = "letsencrypt" ]; then
        if [ "$TLS_DOMAIN" = "_" ] || [ -z "$TLS_DOMAIN" ]; then
            echo "ERROR: Let's Encrypt requires a real TLS_DOMAIN"
            exit 1
        fi
    fi

    echo "Pre-flight checks passed."
}

ensure_service_account() {
    echo "Ensuring dedicated service account..."

    if ! getent group "$SERVICE_GROUP" >/dev/null 2>&1; then
        groupadd --system "$SERVICE_GROUP"
    fi

    if ! id "$SERVICE_USER" >/dev/null 2>&1; then
        useradd \
            --system \
            --gid "$SERVICE_GROUP" \
            --home-dir "$BASE" \
            --shell /usr/sbin/nologin \
            --comment "GNSS Caster service account" \
            "$SERVICE_USER"
    fi

    for supplemental_group in dialout tty bluetooth; do
        if ! getent group "$supplemental_group" >/dev/null 2>&1; then
            groupadd --system "$supplemental_group" 2>/dev/null || true
        fi
        if getent group "$supplemental_group" >/dev/null 2>&1; then
            usermod -a -G "$supplemental_group" "$SERVICE_USER" 2>/dev/null || true
        fi
    done
    ensure_admission_lock
}

# BEGIN GENERATED RELEASE UPDATER
write_release_updater() {
    install -d -o root -g root -m 700 /var/lib/gnss-caster-updates
    cat > "$BASE/release-update.py" << 'PYTHON_RELEASE_UPDATER'
"""Root-owned stable-release updater; stdlib only, no application imports.

The trust boundary is HTTPS GitHub Releases in the fixed owner/repository. An
asset digest verifies integrity, not an independent publisher signature.
"""
import contextlib
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import signal
import sqlite3
import stat
import subprocess
import sys
import tempfile
import time
import urllib.error
import urllib.parse
import urllib.request

REPO = 'stepm65/GNSS-Caster'
API = f'https://api.github.com/repos/{REPO}/releases'
BASE = Path('/opt/gnss-caster')
STORE = Path('/var/lib/gnss-caster-updates')
UNIT = 'gnss-caster-release-update.service'
MAX_ASSET = 20 * 1024 * 1024
MAX_JSON = 1024 * 1024
BUSY = {'queued', 'checking', 'downloading', 'installing'}
STAGE_TIMEOUTS = {'snapshot': 600, 'dependencies': 1800, 'configuration': 900,
                  'migration': 600, 'health': 300, 'rollback': 900}
INSTALL_TIMEOUT = 3600
ROLLBACK_TIMEOUT = 900
HEARTBEAT_SECONDS = 5
CLEAN_ENV = {'PATH': '/usr/sbin:/usr/bin:/sbin:/bin', 'LANG': 'C.UTF-8',
             'HOME': '/root', 'DEBIAN_FRONTEND': 'noninteractive'}


class UpdateError(Exception):
    pass


def version(value):
    match = re.fullmatch(r'v?(0|[1-9][0-9]{0,3})\.(0|[1-9][0-9]{0,3})\.(0|[1-9][0-9]{0,3})', str(value))
    if not match:
        raise UpdateError('Unsupported release version')
    return tuple(map(int, match.groups()))


def current_version():
    source = (BASE / 'app/version.py').read_text(encoding='utf-8')
    match = re.search(r'^__version__ = [\'"]([0-9.]+)[\'"]$', source, re.M)
    if not match:
        raise UpdateError('Cannot determine installed version')
    version(match[1])
    return match[1]


def allowed_url(url):
    parsed = urllib.parse.urlsplit(url)
    return (parsed.scheme == 'https' and parsed.port in (None, 443)
            and not parsed.username and not parsed.password
            and parsed.hostname in {'api.github.com', 'github.com',
                                    'release-assets.githubusercontent.com', 'objects.githubusercontent.com'})


class GitHubRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        if not allowed_url(newurl):
            raise UpdateError('Untrusted download redirect')
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def fetch(url, limit):
    if not allowed_url(url):
        raise UpdateError('Untrusted release URL')
    # Do not let service-controlled proxy environment redirect root traffic.
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}), GitHubRedirect())
    request = urllib.request.Request(url, headers={
        'Accept': 'application/vnd.github+json' if url.startswith(API) else 'application/octet-stream',
        'User-Agent': 'GNSS-Caster-Release-Updater', 'X-GitHub-Api-Version': '2022-11-28',
    })
    deadline = time.monotonic() + (20 if limit == MAX_JSON else 120)
    try:
        with opener.open(request, timeout=10) as response:
            length = int(response.headers.get('Content-Length', '0'))
            if length > limit:
                raise UpdateError('Release download exceeds size limit')
            chunks, total = [], 0
            while True:
                if time.monotonic() > deadline:
                    raise UpdateError('Release download timed out')
                chunk = response.read(min(65536, limit + 1 - total))
                if not chunk:
                    break
                chunks.append(chunk)
                total += len(chunk)
                if total > limit:
                    raise UpdateError('Release download exceeds size limit')
            return b''.join(chunks)
    except urllib.error.HTTPError as error:
        if error.code == 404 and url == API + '/latest':
            return b'null'
        raise UpdateError(f'GitHub request failed (HTTP {error.code})') from error
    except (OSError, ValueError) as error:
        raise UpdateError('Cannot contact GitHub securely; check network and system clock') from error


def release_candidate(data, installed):
    if data is None:
        return None
    if not isinstance(data, dict) or data.get('draft') is not False or data.get('prerelease') is not False:
        raise UpdateError('Only published stable releases are supported')
    tag = data.get('tag_name', '')
    if not re.fullmatch(r'v[0-9]+\.[0-9]+\.[0-9]+', tag):
        raise UpdateError('Unsupported release version')
    target = version(tag)
    assets = [item for item in data.get('assets', []) if item.get('name') == 'gnss-caster-install.sh']
    if len(assets) != 1:
        raise UpdateError('Release has no unique installer asset')
    asset = assets[0]
    digest = str(asset.get('digest') or '')
    if not re.fullmatch(r'sha256:[0-9a-f]{64}', digest):
        raise UpdateError('Release installer has no SHA-256 digest')
    url = f'https://github.com/{REPO}/releases/download/{tag}/gnss-caster-install.sh'
    if asset.get('browser_download_url') != url or asset.get('state') != 'uploaded':
        raise UpdateError('Unexpected release installer URL or state')
    size = asset.get('size')
    if type(size) is not int or not 1 <= size <= MAX_ASSET:
        raise UpdateError('Release installer has an invalid size')
    return {'tag': tag, 'version': '.'.join(map(str, target)), 'sha256': digest[7:],
            'size': size, 'download_url': url, 'available': target > version(installed),
            'url': f'https://github.com/{REPO}/releases/tag/{tag}',
            'notes': str(data.get('body') or '')[:12000], 'published_at': data.get('published_at')}


def ensure_store():
    STORE.mkdir(mode=0o700, parents=False, exist_ok=True)
    info = STORE.lstat()
    if not stat.S_ISDIR(info.st_mode) or info.st_uid != 0 or info.st_mode & 0o077:
        raise UpdateError('Update storage must be a private root-owned directory')


def read_json(name, default=None):
    path = STORE / name
    if not path.exists():
        return default
    info = path.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_nlink != 1:
        raise UpdateError('Unsafe update state file')
    return json.loads(path.read_text(encoding='utf-8'))


def write_json(name, data):
    fd, temporary = tempfile.mkstemp(prefix='.state-', dir=STORE)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as handle:
            json.dump(data, handle, ensure_ascii=True)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, STORE / name)
        if os.name == 'posix':
            directory_fd = os.open(STORE, os.O_RDONLY | os.O_DIRECTORY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


@contextlib.contextmanager
def lock(path):
    import fcntl
    fd = os.open(path, os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_nlink != 1:
            raise UpdateError('Unsafe maintenance lock')
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as error:
            raise UpdateError('Another maintenance operation is running') from error
        yield fd
    finally:
        os.close(fd)


def run(arguments, **kwargs):
    return subprocess.run(arguments, env=CLEAN_ENV, text=True, **kwargs)


def boot_id():
    return Path('/proc/sys/kernel/random/boot_id').read_text().strip()


def recovery_status():
    helper = Path('/var/lib/gnss-caster-maintenance/recovery.py')
    if not helper.exists():
        return []  # Bootstrap from an older runtime without durable journals.
    info = helper.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_mode & 0o022:
        raise UpdateError('Unsafe recovery helper')
    result = run(['/usr/bin/python3', '-I', str(helper), 'status'], capture_output=True, timeout=15)
    if result.returncode:
        raise UpdateError('Cannot read recovery journal; inspect it locally before updating')
    return json.loads(result.stdout)


def status():
    state = read_json('state.json', {'status': 'idle'})
    if state['status'] in BUSY:
        result = run(['/usr/bin/systemctl', 'show', UNIT, '--property=ActiveState', '--value'],
                     capture_output=True, timeout=10)
        active = result.stdout.strip() in ('active', 'activating', 'reloading', 'deactivating')
        if state.get('boot_id') != boot_id() or (not active and time.time() - state['started_at'] > 30):
            # A power cut/SIGKILL is not a successful rollback.
            state = dict(state, status='interrupted', message='Update interrupted; inspect the maintenance log',
                         finished_at=int(time.time()))
            write_json('state.json', state)
    recovery = recovery_status()
    if state['status'] in ('failed', 'interrupted') and state.get('snapshot'):
        restored = next((item for item in recovery
                         if item['snapshot'] == state['snapshot'] and item['phase'] == 'rolled_back'), None)
        if restored:
            state = dict(state, status='rolled_back', message='Previous version restored by local recovery',
                         finished_at=restored['updated_at'])
            write_json('state.json', state)
    installed = current_version()
    checked = read_json('candidate.json')
    if checked and checked.get('candidate'):
        checked['candidate']['available'] = version(checked['candidate']['tag']) > version(installed)
    return {'current_version': installed, 'job': state,
            'release': checked, 'repository': f'https://github.com/{REPO}',
            'recovery': [item for item in recovery if item['phase'] not in ('committed', 'rolled_back', 'snapshot_failed')]}


def check():
    installed = current_version()
    candidate = release_candidate(json.loads(fetch(API + '/latest', MAX_JSON)), installed)
    result = {'checked_at': int(time.time()), 'candidate': candidate}
    write_json('candidate.json', result)
    return dict(result, current_version=installed)


def active_rovers():
    # Read counters only. No import of code/config from the service account.
    path = BASE / 'instance/db.sqlite'
    config = (BASE / 'instance/config.yaml').read_text(encoding='utf-8')
    configured = re.findall(r'^\s+path:\s*[\'"]?([^\s\'"#]+)[\'"]?\s*(?:#.*)?$', config, re.M)
    if configured != [str(path)]:
        raise UpdateError('Web updates require the standard database location')
    with contextlib.closing(sqlite3.connect(path.as_uri() + '?mode=ro', uri=True, timeout=5)) as db:
        field = db.execute("SELECT value FROM system_setting WHERE key='field_work_active'").fetchone()
        if field and str(field[0]).lower() in ('1', 'true', 'yes', 'on'):
            raise UpdateError('Finish field work mode before maintenance')
        return int(db.execute('SELECT COALESCE(SUM(active_conn), 0) FROM rover').fetchone()[0])


def preflight_space():
    # Repair snapshots app, venv and DB. Keep headroom for pip and an additional
    # copy; this is conservative rather than a promise for arbitrary releases.
    total = 0
    for directory in (BASE / 'app', BASE / 'venv', BASE / 'instance'):
        for root, dirs, files in os.walk(directory, followlinks=False):
            for filename in files:
                total += (Path(root) / filename).lstat().st_size
    required = total * 2 + 512 * 1024 * 1024
    for directory in (BASE, Path('/var/backups'), STORE):
        if shutil.disk_usage(directory).free < required:
            raise UpdateError('Not enough free space for update and rollback snapshot')


def start(tag, digest):
    version(tag)
    if not re.fullmatch(r'[0-9a-f]{64}', digest):
        raise UpdateError('Invalid release digest')
    with lock(STORE / 'request.lock'):
        current = status()
        if current['job']['status'] in BUSY:
            raise UpdateError('An update is already running')
        if current.get('recovery'):
            raise UpdateError('Unfinished maintenance requires local recovery before updating')
        checked = read_json('candidate.json', {})
        candidate = checked.get('candidate') or {}
        if time.time() - checked.get('checked_at', 0) > 600 or candidate.get('tag') != tag or candidate.get('sha256') != digest:
            raise UpdateError('Check for updates again before installing')
        if version(tag) <= version(current_version()):
            raise UpdateError('Only a newer release can be installed')
        if active_rovers():
            raise UpdateError('Disconnect all rovers before updating')
        preflight_space()
        # Confirm the other maintenance lock is currently free. The worker
        # obtains and retains it again before doing any work.
        with lock(Path('/run/gnss-caster-maintenance.lock')):
            pass
        run(['/usr/bin/systemctl', 'stop', UNIT], capture_output=True, timeout=15)
        run(['/usr/bin/systemctl', 'reset-failed', UNIT], capture_output=True, timeout=15)
        state = {'status': 'queued', 'tag': tag, 'sha256': digest, 'previous_version': current_version(),
                 'started_at': int(time.time()), 'boot_id': boot_id(), 'message': 'Update queued'}
        write_json('state.json', state)
        try:
            result = run(['/usr/bin/systemd-run', '--unit=' + UNIT, '--property=Type=oneshot',
                          '--property=RemainAfterExit=yes', '--property=UMask=0077',
                          '--property=TimeoutStartSec=infinity', f'--property=TimeoutStopSec={ROLLBACK_TIMEOUT + 60}',
                          '--property=KillMode=mixed', '/usr/bin/python3', '-I',
                          str(BASE / 'release-update.py'), 'worker', tag, digest],
                         capture_output=True, timeout=20)
            if result.returncode:
                raise UpdateError('Could not schedule update service')
        except Exception:
            # Scheduling timeout can be ambiguous; status reconciles with the
            # actual unit, and the API never retries a destructive request.
            raise UpdateError('Update scheduling was not confirmed; check status before retrying')
        return state


def install_asset(candidate, content):
    if len(content) != candidate['size'] or hashlib.sha256(content).hexdigest() != candidate['sha256']:
        raise UpdateError('Downloaded installer failed SHA-256 verification')
    text = content.decode('utf-8')
    match = re.search(r'^CASTER_VERSION="([0-9.]+)"$', text, re.M)
    if not match or match[1] != candidate['version']:
        raise UpdateError('Installer version does not match the release')
    path = STORE / 'installer.sh'
    # The store is root-only; replacement never follows a prior symlink.
    fd, temporary = tempfile.mkstemp(prefix='.installer-', dir=STORE)
    try:
        with os.fdopen(fd, 'wb') as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return path


def record_installer_progress(line, state):
    """Keep recovery coordinates while repair runs, not only after its exit."""
    snapshot = re.fullmatch(r'Rollback snapshot created: (/var/backups/gnss-caster/rollback-[^\s/]+)', line)
    if snapshot:
        state['snapshot'] = snapshot[1]
    if line.startswith('GNSS maintenance stage: '):
        name = line.removeprefix('GNSS maintenance stage: ')
        if name in STAGE_TIMEOUTS:
            state['phase'] = name
    if line == 'Rollback completed; previous service state restored.':
        state['rollback_confirmed'] = True


def run_installation(arguments, *, stdout, pass_fds, state):
    """Forward one stop request and allow rollback before escalating.

    A separate process group lets Bash and its current external command receive
    TERM together. The supervisor stays alive so systemd mixed mode cannot kill
    the rollback immediately after the main process exits.
    """
    requested = []
    previous = {}
    process = None
    stopping_at = None
    phase = 'snapshot'

    def request_stop(signum, frame):
        if not requested:
            requested.append('signal')

    def terminate_group(sig):
        try:
            os.killpg(process.pid, sig)
        except ProcessLookupError:
            pass

    try:
        for sig in (signal.SIGTERM, signal.SIGINT):
            previous[sig] = signal.signal(sig, request_stop)
        if requested:
            raise UpdateError('Update stopped before installation')
        process = subprocess.Popen(arguments, env=CLEAN_ENV, text=True, stdout=stdout,
                                   stderr=subprocess.STDOUT, pass_fds=pass_fds, start_new_session=True)
        started = phase_started = last_heartbeat = time.monotonic()
        phase = state.get('phase', 'snapshot')
        partial = ''
        with (STORE / 'maintenance.log').open(encoding='utf-8', errors='replace') as progress:
            while True:
                chunk = progress.read(256 * 1024)
                lines = (partial + chunk).split('\n')
                partial = lines.pop()[-65536:]
                coordinates = (state.get('snapshot'), state.get('phase'), state.get('rollback_confirmed'))
                for line in lines:
                    record_installer_progress(line.strip(), state)
                if coordinates != (state.get('snapshot'), state.get('phase'), state.get('rollback_confirmed')):
                    write_json('state.json', state)
                now = time.monotonic()
                next_phase = state.get('phase', phase)
                if next_phase != phase:
                    phase, phase_started = next_phase, now
                result = process.poll()
                if result is not None:
                    # Drain the remaining log before accepting a final result.
                    if chunk:
                        continue
                    record_installer_progress(partial.strip(), state)
                    return subprocess.CompletedProcess(arguments, result)
                if not requested and (now - started >= INSTALL_TIMEOUT or
                                      now - phase_started >= STAGE_TIMEOUTS.get(phase, 900)):
                    requested.append('timeout')
                if requested and stopping_at is None:
                    state['stop_reason'] = requested[0]
                    state['stop_requested_at'] = int(time.time())
                    state['message'] = 'Stopping update; waiting for rollback'
                    write_json('state.json', state)
                    # A rollback triggered by repair itself must not be interrupted.
                    if phase != 'rollback':
                        terminate_group(signal.SIGTERM)
                    stopping_at = now
                if stopping_at is not None and now - stopping_at >= ROLLBACK_TIMEOUT:
                    state['termination_escalated'] = True
                    write_json('state.json', state)
                    terminate_group(signal.SIGKILL)
                    process.wait(timeout=30)
                    raise UpdateError('Update could not stop safely; inspect the recovery snapshot')
                if now - last_heartbeat >= HEARTBEAT_SECONDS:
                    state['heartbeat_at'] = int(time.time())
                    write_json('state.json', state)
                    last_heartbeat = now
                try:
                    process.wait(timeout=1)
                except subprocess.TimeoutExpired:
                    pass
    finally:
        # An exception in state/log handling must not leave an untracked installer.
        try:
            if process is not None and process.poll() is None:
                if stopping_at is None and phase != 'rollback':
                    terminate_group(signal.SIGTERM)
                try:
                    process.wait(timeout=ROLLBACK_TIMEOUT)
                except subprocess.TimeoutExpired:
                    terminate_group(signal.SIGKILL)
                    process.wait(timeout=30)
        finally:
            for sig, handler in previous.items():
                signal.signal(sig, handler)


def worker(tag, digest):
    state = read_json('state.json')
    if not state or state.get('tag') != tag or state.get('sha256') != digest or state['status'] != 'queued':
        raise UpdateError('No matching update request')

    def stage(name, message):
        state.update(status=name, message=message)
        write_json('state.json', state)

    try:
        with lock(Path('/run/gnss-caster-maintenance.lock')) as maintenance_fd:
            (STORE / 'maintenance.log').write_text(f'Updating to {tag}\n', encoding='utf-8')
            stage('checking', 'Validating stable release')
            candidate = release_candidate(json.loads(fetch(API + '/tags/' + tag, MAX_JSON)), current_version())
            if not candidate or not candidate['available'] or candidate['sha256'] != digest:
                raise UpdateError('Release changed; check for updates again')
            if active_rovers():
                raise UpdateError('Disconnect all rovers before updating')
            preflight_space()
            stage('downloading', 'Downloading and verifying installer')
            path = install_asset(candidate, fetch(candidate['download_url'], MAX_ASSET))
            syntax = run(['/bin/bash', '-n', str(path)], capture_output=True, timeout=15)
            if syntax.returncode:
                raise UpdateError('Release installer syntax check failed')
            if active_rovers():
                raise UpdateError('Disconnect all rovers before updating')
            # Existing repair transaction uses fd 8. Pass the same open-file
            # description so child flock recognizes ownership without bypasses.
            os.dup2(maintenance_fd, 8, inheritable=True)
            try:
                stage('installing', 'Installing; web interface may reconnect')
                with (STORE / 'maintenance.log').open('a', encoding='utf-8') as log:
                    result = run_installation(['/bin/bash', str(path), '--repair'], stdout=log,
                                              pass_fds=(8,), state=state)
                rolled_back = False
                with (STORE / 'maintenance.log').open(encoding='utf-8', errors='replace') as log:
                    for line in iter(lambda: log.readline(65536), ''):
                        snapshot = re.fullmatch(r'Rollback snapshot created: (/var/backups/gnss-caster/[^\s]+)\s*', line)
                        if snapshot:
                            state['snapshot'] = snapshot[1]
                        if line.strip() == 'Rollback completed; previous service state restored.':
                            rolled_back = True
                if result.returncode or state.get('stop_reason'):
                    if rolled_back:
                        stage('rolled_back', 'Update failed; previous version restored')
                    else:
                        stage('failed', 'Update failed; inspect the maintenance log')
                elif current_version() != candidate['version']:
                    stage('failed', 'Installed version could not be confirmed; inspect the maintenance log')
                else:
                    stage('succeeded', 'Update installed successfully; reload the page')
            finally:
                if maintenance_fd != 8:
                    os.close(8)
    except Exception as error:
        message = str(error) if isinstance(error, UpdateError) else 'Update failed; inspect the maintenance log'
        stage('interrupted' if state.get('termination_escalated') else 'failed', message)
    finally:
        state['finished_at'] = int(time.time())
        write_json('state.json', state)
    return state


def main():
    if os.geteuid() != 0:
        raise UpdateError('Updater requires root')
    os.umask(0o077)
    ensure_store()
    args = sys.argv[1:]
    if args == ['check']:
        result = check()
    elif args == ['status']:
        result = status()
    elif len(args) == 3 and args[0] == 'start':
        result = start(*args[1:])
    elif len(args) == 3 and args[0] == 'worker':
        result = worker(*args[1:])
    else:
        raise UpdateError('Unsupported updater command')
    print(json.dumps(result, ensure_ascii=True))


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        print(json.dumps({'error': str(error) if isinstance(error, UpdateError) else 'Update operation failed'}))
        sys.exit(1)

PYTHON_RELEASE_UPDATER
    chown root:root "$BASE/release-update.py"
    chmod 700 "$BASE/release-update.py"
}
