# ----------------- DATABASE MODELS -----------------
# SQLAlchemy models (app/db/models.py): admins, base stations, mount points,
# rovers, RTCM settings, receiver config versions, command/log tables, API tokens.
echo "Creating database models..."
cat > $APP/db/models.py << 'EOF'
from flask_sqlalchemy import SQLAlchemy
from flask_login import UserMixin
import time
import os
import tempfile

db = SQLAlchemy()

def write_private_text(path, content):
    """Publish a complete private file without following a destination symlink."""
    directory = os.path.dirname(os.path.abspath(path))
    os.makedirs(directory, exist_ok=True)
    descriptor, temporary = tempfile.mkstemp(prefix='.gnss-secret-', dir=directory)
    try:
        with os.fdopen(descriptor, 'w', encoding='utf-8') as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)

class Admin(UserMixin, db.Model):
    __tablename__ = 'admin'
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(32), unique=True, nullable=False)
    password = db.Column(db.String(128), nullable=False)
    role = db.Column(db.String(20), default='admin')
    email = db.Column(db.String(128))
    last_login = db.Column(db.Integer, default=0)
    login_attempts = db.Column(db.Integer, default=0)
    locked_until = db.Column(db.Integer, default=0)
    must_change_password = db.Column(db.Boolean, default=False)
    totp_secret = db.Column(db.String(64), default='')      # base32 TOTP secret
    totp_enabled = db.Column(db.Boolean, default=False)     # 2FA active for this admin
    totp_backup_codes = db.Column(db.Text, default='')      # JSON list of hashed one-time backup codes
    totp_pending_secret = db.Column(db.String(64), default='')
    totp_pending_expires = db.Column(db.Integer, default=0)
    session_version = db.Column(db.Integer, nullable=False, default=0)
    created_at = db.Column(db.Integer, default=lambda: int(time.time()))
    updated_at = db.Column(db.Integer, default=lambda: int(time.time()))
    
    def set_password_hash(self, password_hash):
        self.password = password_hash
        # SQL expression increments the stored version even when another
        # transaction revoked sessions after this object was loaded.
        self.session_version = Admin.session_version + 1
        self.totp_pending_secret = ''
        self.totp_pending_expires = 0

    def get_id(self):
        return f'{self.id}:{int(self.session_version or 0)}'

    def is_locked(self):
        return self.locked_until > time.time()

class ApiToken(db.Model):
    """API token for external integrations (Fix #20).

    Tokens allow read-mostly programmatic access (Grafana, Prometheus, n8n,
    monitoring scripts) without a session cookie. Only a SHA-256 hash of the
    token is stored; the plaintext is shown exactly once at creation time.
    """
    __tablename__ = 'api_token'
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(64), nullable=False)
    # SHA-256 hex digest of the token (never store plaintext)
    token_hash = db.Column(db.String(64), unique=True, nullable=False, index=True)
    # First 8 chars of the token, shown in the UI to identify it
    token_prefix = db.Column(db.String(12), default='')
    # Which admin created it (audit)
    created_by = db.Column(db.String(64), default='')
    # Optional scope: 'read' (GET only) or 'full'
    scope = db.Column(db.String(16), default='read')
    is_active = db.Column(db.Boolean, default=True)
    last_used = db.Column(db.Integer, default=0)
    expires = db.Column(db.Integer, default=0)  # 0 = never expires
    created_at = db.Column(db.Integer, default=lambda: int(time.time()))

    def is_expired(self):
        return self.expires > 0 and self.expires < time.time()

class BaseStation(db.Model):
    __tablename__ = 'base_station'
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(32), unique=True, nullable=False)
    bt_mac = db.Column(db.String(17), nullable=False)
    channel = db.Column(db.Integer, default=1)
    connection_type = db.Column(db.String(16), default='bluetooth')
    gnss_port = db.Column(db.String(64), default='/dev/rfcomm1')
    baudrate = db.Column(db.Integer, default=115200)
    data_bits = db.Column(db.Integer, default=8)
    stop_bits = db.Column(db.Integer, default=1)
    parity = db.Column(db.String(1), default='N')
    data_type = db.Column(db.String(16), default='RTCM3')
    output_interval = db.Column(db.Integer, default=1)
    position_mode = db.Column(db.String(16), default='auto')
    position_accuracy = db.Column(db.Float, default=1.0)
    manual_lat = db.Column(db.Float, default=0.0)
    manual_lon = db.Column(db.Float, default=0.0)
    manual_alt = db.Column(db.Float, default=0.0)
    operation_mode = db.Column(db.String(20), default='base')
    receiver_brand = db.Column(db.String(32), default='comnav')
    survey_duration_sec = db.Column(db.Integer, default=30)
    antenna_height = db.Column(db.Float, default=0.0)
    # When true, antenna_height is added to manual_alt before it is sent to the
    # receiver, so changing tripods only means editing the antenna height.
    add_antenna_height = db.Column(db.Boolean, default=False)
    # Reported by the receiver itself in response to VERSION. Useful when a
    # firmware change alters behaviour - BeiDou PRN renumbering, for one.
    receiver_model = db.Column(db.String(64), default='')
    firmware_version = db.Column(db.String(64), default='')
    firmware_date = db.Column(db.String(32), default='')
    receiver_serial = db.Column(db.String(64), default='')
    antenna_type = db.Column(db.String(128), default='')
    antenna_serial = db.Column(db.String(128), default='')
    command_strategy = db.Column(db.String(16), default='generated')
    startup_commands = db.Column(db.Text, default='')
    shutdown_commands = db.Column(db.Text, default='')
    status = db.Column(db.String(20), default='disconnected')
    last_seen = db.Column(db.Integer, default=0)
    bytes_received = db.Column(db.Integer, default=0)
    bytes_sent = db.Column(db.Integer, default=0)
    created_at = db.Column(db.Integer, default=lambda: int(time.time()))
    updated_at = db.Column(db.Integer, default=lambda: int(time.time()))

class MountPoint(db.Model):
    __tablename__ = 'mountpoint'
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(32), unique=True, nullable=False)
    base_id = db.Column(db.Integer, db.ForeignKey('base_station.id'), nullable=False)
    description = db.Column(db.String(255))
    is_active = db.Column(db.Boolean, default=True)
    rtcm_settings = db.Column(db.Text, default='{}')  # JSON string for RTCM message settings
    created_at = db.Column(db.Integer, default=lambda: int(time.time()))
    updated_at = db.Column(db.Integer, default=lambda: int(time.time()))
    
    base_station = db.relationship('BaseStation', backref='mountpoints')

class Rover(db.Model):
    __tablename__ = 'rover'
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(32), unique=True, nullable=False)
    password = db.Column(db.String(128), nullable=False)
    email = db.Column(db.String(128))
    mountpoints = db.Column(db.String(512))
    max_conn = db.Column(db.Integer, default=1)
    active_conn = db.Column(db.Integer, default=0)
    expires = db.Column(db.Integer, default=0)
    last_connection = db.Column(db.Integer, default=0)
    total_connections = db.Column(db.Integer, default=0)
    is_active = db.Column(db.Boolean, default=True)
    created_at = db.Column(db.Integer, default=lambda: int(time.time()))
    updated_at = db.Column(db.Integer, default=lambda: int(time.time()))

class RTCMSetting(db.Model):
    __tablename__ = 'rtcm_setting'
    id = db.Column(db.Integer, primary_key=True)
    msg_type = db.Column(db.Integer, unique=True, nullable=False)
    enabled = db.Column(db.Boolean, default=True)
    description = db.Column(db.String(255))
    version = db.Column(db.String(10), default='3.2')
    group = db.Column(db.String(50))
    created_at = db.Column(db.Integer, default=lambda: int(time.time()))
    updated_at = db.Column(db.Integer, default=lambda: int(time.time()))

class LogEntry(db.Model):
    __tablename__ = 'log_entry'
    __table_args__ = (
        db.Index('ix_log_entry_timestamp', 'timestamp'),
        db.Index('ix_log_entry_level_ts', 'level', 'timestamp'),
        db.Index('ix_log_entry_module_ts', 'module', 'timestamp'),
    )
    id = db.Column(db.Integer, primary_key=True)
    level = db.Column(db.String(20))
    module = db.Column(db.String(64))
    message = db.Column(db.Text)
    timestamp = db.Column(db.Integer, default=lambda: int(time.time()))
    ip_address = db.Column(db.String(45))

class CommandLog(db.Model):
    """Records every receiver command sent and the response received."""
    __tablename__ = 'command_log'
    id        = db.Column(db.Integer, primary_key=True)
    station_id = db.Column(db.Integer, db.ForeignKey('base_station.id', ondelete='CASCADE'), nullable=False, index=True)
    phase     = db.Column(db.String(32), default='manual')   # startup / shutdown / manual / test-*
    command   = db.Column(db.String(512), nullable=False)
    response  = db.Column(db.Text, default='')
    ts        = db.Column(db.Integer, default=lambda: int(time.time()), index=True)

    station = db.relationship(
        'BaseStation',
        backref=db.backref(
            'command_logs',
            lazy='dynamic',
            # Command history belongs to the station: without the cascade the
            # ORM tries to NULL the NOT NULL station_id on delete and the whole
            # deletion fails with an IntegrityError.
            cascade='all, delete-orphan',
        ),
    )

class ReceiverConfigVersion(db.Model):
    """Immutable snapshot of a base station's receiver configuration (Fix #17).

    A new row is written whenever the config-bearing fields of a BaseStation
    change (startup/shutdown commands, command strategy, position mode, etc.)
    or when a config is applied to the receiver. This gives an audit trail and
    lets the operator diff/restore previous configurations.
    """
    __tablename__ = 'receiver_config_version'
    __table_args__ = (
        db.Index('ix_rcv_cfg_station_ts', 'station_id', 'created_at'),
    )
    id = db.Column(db.Integer, primary_key=True)
    station_id = db.Column(
        db.Integer,
        db.ForeignKey('base_station.id', ondelete='CASCADE'),
        nullable=False, index=True
    )
    # Monotonic per-station version number (1, 2, 3, …)
    version = db.Column(db.Integer, nullable=False, default=1)
    # JSON snapshot of the config-bearing fields
    config_json = db.Column(db.Text, nullable=False, default='{}')
    # What triggered the snapshot: 'edit' | 'apply' | 'initial' | 'restore'
    source = db.Column(db.String(16), default='edit')
    # Optional human note and who made the change
    note = db.Column(db.String(255), default='')
    created_by = db.Column(db.String(64), default='')
    created_at = db.Column(db.Integer, default=lambda: int(time.time()), index=True)

    station = db.relationship(
        'BaseStation',
        backref=db.backref(
            'config_versions',
            lazy='dynamic',
            # Delete a station's config-version history together with the
            # station. Without this the ORM tries to NULL the NOT NULL
            # station_id on delete and raises IntegrityError; delete-orphan
            # makes SQLAlchemy remove the child rows explicitly (no dependency
            # on SQLite's PRAGMA foreign_keys, which is off by default).
            cascade='all, delete-orphan',
        )
    )

class Backup(db.Model):
    __tablename__ = 'backup'
    id = db.Column(db.Integer, primary_key=True)
    filename = db.Column(db.String(255))
    size_bytes = db.Column(db.Integer)
    created_at = db.Column(db.Integer, default=lambda: int(time.time()))
    description = db.Column(db.String(255))

class PositionSample(db.Model):
    """Periodic record of where the base says it is.

    Answers, after the fact, whether the base stood still for the whole survey.
    If measurements later look wrong, this shows what the base was doing at the
    time instead of leaving it to guesswork. Rows are small and pruned with the
    rest of the history.
    """
    __tablename__ = 'position_sample'
    id = db.Column(db.Integer, primary_key=True)
    station_id = db.Column(
        db.Integer, db.ForeignKey('base_station.id', ondelete='CASCADE'),
        nullable=False, index=True,
    )
    ts = db.Column(db.Integer, default=lambda: int(time.time()), index=True)
    latitude = db.Column(db.Float)
    longitude = db.Column(db.Float)
    altitude = db.Column(db.Float)
    offset_m = db.Column(db.Float)          # distance from the configured point
    satellites = db.Column(db.Integer)
    hdop = db.Column(db.Float)
    fix_quality = db.Column(db.String(32))


class SitePoint(db.Model):
    """A saved survey point: coordinates plus the antenna setup used there.

    Re-typing coordinates for every visit is slow and, more importantly, one
    wrong digit in a latitude silently shifts every measurement taken that day.
    Saving them once removes that risk.
    """
    __tablename__ = 'site_point'
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(120), unique=True, nullable=False)
    description = db.Column(db.String(255), default='')
    latitude = db.Column(db.Float, nullable=False)
    longitude = db.Column(db.Float, nullable=False)
    altitude = db.Column(db.Float, default=0.0)
    antenna_height = db.Column(db.Float, default=0.0)
    add_antenna_height = db.Column(db.Boolean, default=False)
    created_at = db.Column(db.Integer, default=lambda: int(time.time()))
    updated_at = db.Column(db.Integer, default=lambda: int(time.time()))
    last_used_at = db.Column(db.Integer)


class SystemSetting(db.Model):
    __tablename__ = 'system_setting'
    id = db.Column(db.Integer, primary_key=True)
    key = db.Column(db.String(50), unique=True, nullable=False)
    value = db.Column(db.Text)
    description = db.Column(db.String(255))
    created_at = db.Column(db.Integer, default=lambda: int(time.time()))
    updated_at = db.Column(db.Integer, default=lambda: int(time.time()))
