def _run_power_action(action):
    """Restart the service or reboot the host, via the privileged helper."""
    try:
        from app.bluetooth.core import _run_privileged_helper
    except Exception as import_error:
        return f'Cannot do that: {import_error}'

    command = 'reboot-host' if action == 'reboot' else 'restart-service'
    try:
        result = _run_privileged_helper([command], timeout=30)
    except Exception as run_error:
        return f'Could not run it: {run_error}'

    if result.returncode != 0:
        return f'Failed: {(result.stderr or "").strip()[:160]}'

    if action == 'reboot':
        return (
            '\U0001f501 Rebooting in a few seconds. The caster will be back in '
            'about a minute; you will get a "started" message when it is.'
        )
    return (
        '\U0001f501 Restarting the caster service. It should be back within '
        'about ten seconds.'
    )


CONFIRM_KEYBOARDS = {
    'reboot': {'inline_keyboard': [[
        {'text': '\u26a0\ufe0f Yes, reboot the host', 'callback_data': 'reboot_confirm'},
        {'text': 'Cancel', 'callback_data': 'help'},
    ]]},
    'restart': {'inline_keyboard': [[
        {'text': '\u21bb Yes, restart the service', 'callback_data': 'restart_confirm'},
        {'text': 'Cancel', 'callback_data': 'help'},
    ]]},
}


def _describe_server(app, language='en'):
    """Host health: the things that actually strand a field unit.

    Disk filling up, the card overheating, memory exhausted or a service that
    quietly died - none of which show up in the GNSS status but all of which
    end a survey.
    """
    lines = ['\U0001f5a5 Server']

    # Uptime
    try:
        with open('/proc/uptime', 'r') as handle:
            seconds = float(handle.read().split()[0])
        days, rest = divmod(int(seconds), 86400)
        hours, rest = divmod(rest, 3600)
        minutes = rest // 60
        uptime = f'{days}d {hours}h {minutes}m' if days else f'{hours}h {minutes}m'
        if language == 'ru':
            uptime = f'{days} д {hours} ч {minutes} мин' if days else f'{hours} ч {minutes} мин'
        lines.append(f'Uptime: {uptime}')
    except Exception:
        pass

    # Temperature - a Pi in a sealed box in the sun will throttle
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as handle:
            celsius = int(handle.read().strip()) / 1000.0
        warning = (' ⚠️ перегрев' if language == 'ru' else ' ⚠️ hot') if celsius >= 75 else ''
        lines.append(f'Temperature: {celsius:.0f}\u00b0C{warning}')
    except Exception:
        pass

    # Disk and memory
    try:
        import shutil

        usage = shutil.disk_usage('/')
        free_gb = usage.free / (1024 ** 3)
        used_pct = 100.0 * (usage.total - usage.free) / usage.total
        warning = (' ⚠️ мало места' if language == 'ru' else ' ⚠️ low') if free_gb < 1.0 else ''
        lines.append(f'Disk: {free_gb:.1f} GB free ({used_pct:.0f}% used){warning}')
    except Exception:
        pass

    try:
        meminfo = {}
        with open('/proc/meminfo', 'r') as handle:
            for line in handle:
                key, _, value = line.partition(':')
                meminfo[key.strip()] = value.strip()
        total_kb = int(meminfo.get('MemTotal', '0 kB').split()[0])
        available_kb = int(meminfo.get('MemAvailable', '0 kB').split()[0])
        if total_kb:
            lines.append(
                f'Memory: {available_kb / 1024:.0f} MB free of {total_kb / 1024:.0f} MB'
            )
    except Exception:
        pass

    # Load average
    try:
        load1, load5, _ = os.getloadavg()
        lines.append(f'Load: {load1:.2f} (5 min {load5:.2f})')
    except Exception:
        pass

    # Latest backup - a stale backup is worth knowing about
    try:
        backup_dir = '/opt/gnss-caster/backups'
        archives = [
            os.path.join(backup_dir, name)
            for name in os.listdir(backup_dir)
            if name.startswith('backup_')
        ]
        if archives:
            newest = max(archives, key=os.path.getmtime)
            age_hours = (time.time() - os.path.getmtime(newest)) / 3600.0
            age = f'{age_hours:.0f} h ago' if age_hours < 48 else f'{age_hours / 24:.0f} days ago'
            size_mb = os.path.getsize(newest) / (1024 ** 2)
            age = translate_bot(age, language)
            lines.append(f'Last backup: {age} ({size_mb:.1f} MB)')
        else:
            lines.append('Last backup: none yet')
    except Exception:
        pass

    return '\n'.join(lines)


def _start_backup(app):
    """Kick off a backup the same way the web interface does.

    Runs as a systemd transient unit through the privileged helper, so it
    survives this thread and behaves identically whether it was triggered from
    a browser or a chat. The archive lands in the chat by itself if uploads are
    enabled.
    """
    try:
        from app.bluetooth.core import _run_privileged_helper
    except Exception as import_error:
        return f'Cannot start a backup: {import_error}'

    unit_name = f'gnss-caster-backup-{int(time.time())}.service'
    try:
        result = _run_privileged_helper(
            ['systemd-job', 'backup', unit_name], timeout=30
        )
    except Exception as run_error:
        return f'Could not start the backup: {run_error}'

    if result.returncode != 0:
        return f'Backup could not be started: {(result.stderr or "").strip()[:160]}'

    return (
        'Backup started. It usually takes under a minute; the archive will '
        'arrive here if uploads are enabled.'
    )


def _describe_readiness(app, language='en'):
    """Readiness as a short message for a phone screen."""
    try:
        from app.bluetooth.core import bluetooth_manager

        report = bluetooth_manager.get_readiness()
    except Exception as readiness_error:
        return f'Readiness unavailable: {readiness_error}'

    if report.get('ready'):
        lines = ['\u2705 READY to survey']
    else:
        lines = ['\u26d4 NOT ready']

    for station in report.get('stations', []):
        mark = '\u2705' if station.get('ready') else '\u26d4'
        detail = []
        if station.get('satellites') is not None:
            detail.append(translate_bot(f"{station['satellites']} sats", language))
        if station.get('hdop') is not None:
            detail.append(f"HDOP {station['hdop']}")
        if station.get('fix'):
            detail.append(str(station['fix']))
        detail.append(translate_bot(f"{station.get('rovers', 0)} rover(s)", language))
        lines.append(f"{mark} {station.get('name')} - {', '.join(detail)}")
        for issue in station.get('issues', []):
            lines.append(f'    \u2022 {translate_bot(issue, language)}')

    for issue in report.get('issues', []):
        if not any(issue.startswith(f"{s.get('name')}:") for s in report.get('stations', [])):
            lines.append(f'\u2022 {issue}')

    return '\n'.join(lines)


def _describe_status(app, language='en'):
    try:
        from app.bluetooth.core import bluetooth_manager
        from app.rtcm.stream import stream_manager

        status = bluetooth_manager.get_status()
        connected = status.get('connected', 0)
        total = status.get('total_stations', 0)
        lines = [f'Stations: {connected}/{total} connected']
        for station in status.get('stations', []):
            state = 'connected' if station.get('connected') else (station.get('status') or 'disconnected')
            state = translate_bot(state, language)
            rate = (station.get('telemetry') or {}).get('data_rate_bps', 0) or 0
            lines.append(f"  - {station.get('name')}: {state}, {rate/1024:.1f} KB/s")
            if station.get('last_error') and not station.get('connected'):
                lines.append(f"    last error: {station['last_error'][:120]}")
        try:
            rover_total = sum(
                int((stats or {}).get('clients', 0) or 0)
                for stats in (stream_manager.get_stats() or {}).values()
            )
            lines.append(f'Rovers connected: {rover_total}')
        except Exception:
            pass
        return '\n'.join(lines)
    except Exception as status_error:
        return f'Status unavailable: {status_error}'


def _describe_rovers(app):
    try:
        from app.rtcm.stream import stream_manager

        stats = stream_manager.get_stats() or {}
        if not stats:
            return 'No active streams.'
        lines = []
        for base_id, entry in stats.items():
            clients = int((entry or {}).get('clients', 0) or 0)
            frames = int((entry or {}).get('frames_parsed', 0) or 0)
            lines.append(f'Base {base_id}: {clients} rover(s), {frames} frames decoded')
        return '\n'.join(lines)
    except Exception as rovers_error:
        return f'Rover information unavailable: {rovers_error}'


def _describe_events(settings):
    language = settings.get('language', 'en')
    lines = [translate_bot('Notifications:', language)]
    for key, label in EVENT_TYPES:
        state = 'on' if settings['events'].get(key, True) else 'off'
        lines.append(f"  {key.replace('notify_', ''):18s} {translate_bot(state, language)}  ({translate_bot(label, language)})")
    lines.append('')
    lines.append('Master switch: ' + translate_bot('on' if settings['enabled'] else 'off', language))
    return '\n'.join(lines)


def _handle_command_raw(app, settings, text):
    """Return the reply for a command, or None to stay silent."""
    parts = str(text or '').strip().split()
    if not parts:
        return None
    command = parts[0].lower().split('@')[0]
    argument = parts[1].lower() if len(parts) > 1 else ''

    if command in ('/start', '/help'):
        return HELP_TEXT
    if command == '/restart':
        return ('Restart the caster service? Rovers will lose corrections for '
                'a few seconds.', CONFIRM_KEYBOARDS['restart'])
    if command == '/restart_confirm':
        return _run_power_action('restart')
    if command == '/reboot':
        return ('Reboot the whole machine? Everything stops for about a minute. '
                'Try /restart first - it fixes most things.',
                CONFIRM_KEYBOARDS['reboot'])
    if command == '/reboot_confirm':
        return _run_power_action('reboot')
    if command in ('/server', '/host'):
        return _describe_server(app, settings.get('language', 'en'))
    if command == '/backup':
        return _start_backup(app)
    if command in ('/ready', '/readiness'):
        return _describe_readiness(app, settings.get('language', 'en'))
    if command == '/status':
        return _describe_readiness(app, settings.get('language', 'en')) + '\n\n' + _describe_status(app, settings.get('language', 'en'))
    if command == '/stations':
        return _describe_status(app, settings.get('language', 'en'))
    if command == '/rovers':
        return _describe_rovers(app)
    if command == '/events':
        return _describe_events(settings)
    if command == '/mute':
        _set_setting(app, 'telegram_enabled', 'false')
        return 'Notifications muted. Send /unmute to resume.'
    if command == '/unmute':
        _set_setting(app, 'telegram_enabled', 'true')
        return 'Notifications resumed.'
    if command in ('/on', '/off'):
        if not argument:
            return 'Usage: /on <event>\n\n' + _describe_events(settings)
        key = argument if argument.startswith('notify_') else f'notify_{argument}'
        if key not in dict(EVENT_TYPES):
            return f'Unknown event "{argument}".\n\n' + _describe_events(settings)
        _set_setting(app, key, 'true' if command == '/on' else 'false')
        return f"{key.replace('notify_', '')} is now {'on' if command == '/on' else 'off'}"
    return None


