        # API Routes
        @app.route('/api/status')
        @login_required
        def api_status():
            try:
                import psutil
                import platform

                def read_cpu_temp_c():
                    # Try psutil sensors first.
                    try:
                        temps = psutil.sensors_temperatures(fahrenheit=False) or {}
                    except Exception:
                        temps = {}

                    preferred_keys = ('cpu_thermal', 'coretemp', 'k10temp', 'soc_thermal', 'acpitz')
                    for key in preferred_keys:
                        entries = temps.get(key) or []
                        for entry in entries:
                            current = getattr(entry, 'current', None)
                            if current is not None:
                                return float(current)

                    for entries in temps.values():
                        for entry in entries:
                            label = (getattr(entry, 'label', '') or '').lower()
                            current = getattr(entry, 'current', None)
                            if current is None:
                                continue
                            if any(token in label for token in ('cpu', 'package', 'core', 'soc', 'thermal', 'tctl')):
                                return float(current)

                    for entries in temps.values():
                        for entry in entries:
                            current = getattr(entry, 'current', None)
                            if current is not None:
                                return float(current)

                    # Fallback common Linux thermal file.
                    thermal_path = '/sys/class/thermal/thermal_zone0/temp'
                    if os.path.exists(thermal_path):
                        try:
                            with open(thermal_path, 'r') as f:
                                raw = f.read().strip()
                            milli = int(raw)
                            return milli / 1000.0 if milli > 1000 else float(milli)
                        except Exception:
                            pass

                    # Raspberry Pi fallback via vcgencmd
                    try:
                        out = subprocess.check_output(
                            ['vcgencmd', 'measure_temp'],
                            stderr=subprocess.DEVNULL,
                            text=True,
                            timeout=2,
                            env=_build_subprocess_env()
                        ).strip()
                        # Example: "temp=48.6'C"
                        if out.startswith('temp='):
                            temp_text = out.split('=', 1)[1].split("'", 1)[0]
                            return float(temp_text)
                    except Exception:
                        pass

                    return None

                def read_fan_rpm():
                    # Try psutil fan sensors.
                    try:
                        fans = psutil.sensors_fans() or {}
                    except Exception:
                        fans = {}

                    for entries in fans.values():
                        for entry in entries:
                            current = getattr(entry, 'current', None)
                            if current is not None:
                                return int(current)

                    # Fallback common Linux hwmon files.
                    hwmon_base = '/sys/class/hwmon'
                    if os.path.isdir(hwmon_base):
                        for hwmon_dir in sorted(os.listdir(hwmon_base)):
                            hwmon_path = os.path.join(hwmon_base, hwmon_dir)
                            try:
                                for fname in sorted(os.listdir(hwmon_path)):
                                    if not fname.startswith('fan') or not fname.endswith('_input'):
                                        continue
                                    fpath = os.path.join(hwmon_path, fname)
                                    with open(fpath, 'r') as f:
                                        raw = f.read().strip()
                                    rpm = int(raw)
                                    if rpm > 0:
                                        return rpm
                            except Exception:
                                continue

                    return None

                def read_fan_status(fan_rpm_value):
                    if fan_rpm_value is not None:
                        return 'ON' if int(fan_rpm_value) > 0 else 'OFF'

                    # Linux thermal cooling devices fallback
                    thermal_base = '/sys/class/thermal'
                    if os.path.isdir(thermal_base):
                        for entry in sorted(os.listdir(thermal_base)):
                            if not entry.startswith('cooling_device'):
                                continue
                            cd_path = os.path.join(thermal_base, entry)
                            cur_state_path = os.path.join(cd_path, 'cur_state')
                            max_state_path = os.path.join(cd_path, 'max_state')
                            try:
                                with open(cur_state_path, 'r') as f:
                                    cur_state = int(f.read().strip())
                                with open(max_state_path, 'r') as f:
                                    max_state = int(f.read().strip())
                                if max_state > 0:
                                    return 'ON' if cur_state > 0 else 'OFF'
                            except Exception:
                                continue

                    return None
                
                # System info
                system_info = {
                    'platform': platform.platform(),
                    'python_version': platform.python_version(),
                    'hostname': platform.node()
                }
                
                def read_wifi_link():
                    """Signal strength of the host's own Wi-Fi link, or None.

                    Reads /proc/net/wireless, which the kernel exposes without
                    any privileges or extra dependencies. SSID and bitrate are
                    not in that file, so they are fetched best-effort with "iw"
                    (installed by the installer) and simply omitted if that
                    fails - the signal reading never depends on it.
                    """
                    try:
                        with open('/proc/net/wireless', 'r') as wireless_file:
                            lines = wireless_file.readlines()
                    except OSError:
                        return None

                    # The first two lines are headers; data rows look like:
                    #   wlan0: 0000   70.  -40.  -256        0 ...
                    for line in lines[2:]:
                        if ':' not in line:
                            continue
                        interface_name, _, remainder = line.partition(':')
                        interface_name = interface_name.strip()
                        fields = remainder.split()
                        if len(fields) < 3:
                            continue
                        try:
                            # Values carry a trailing dot (e.g. "-40.").
                            link_quality = float(fields[1].rstrip('.'))
                            signal_dbm = float(fields[2].rstrip('.'))
                        except (TypeError, ValueError):
                            continue

                        # Skip interfaces that are up but not associated.
                        if signal_dbm == 0 and link_quality == 0:
                            continue

                        wifi = {
                            'interface': interface_name,
                            'signal_dbm': int(signal_dbm),
                            'link_quality': int(link_quality),
                            'ssid': None,
                            'bitrate': None,
                        }

                        try:
                            import subprocess as _sp
                            link_output = _sp.run(
                                ['iw', 'dev', interface_name, 'link'],
                                capture_output=True, text=True, timeout=3
                            ).stdout
                            for link_line in link_output.splitlines():
                                stripped = link_line.strip()
                                if stripped.startswith('SSID:'):
                                    wifi['ssid'] = stripped.split(':', 1)[1].strip() or None
                                elif stripped.startswith('tx bitrate:'):
                                    wifi['bitrate'] = stripped.split(':', 1)[1].strip() or None
                        except Exception:
                            # iw missing, not permitted, or slow - signal still stands.
                            pass

                        return wifi

                    return None

                # Resources
                cpu_temp_c = read_cpu_temp_c()
                fan_rpm = read_fan_rpm()
                fan_status = read_fan_status(fan_rpm)
                resources = {
                    'cpu_percent': psutil.cpu_percent(interval=None),
                    'memory_percent': psutil.virtual_memory().percent,
                    'disk_percent': psutil.disk_usage('/').percent,
                    'cpu_temp_c': cpu_temp_c,
                    'fan_rpm': fan_rpm,
                    'fan_status': fan_status,
                    'wifi': read_wifi_link()
                }
                
                # Database stats
                db_stats = {
                    'base_stations': BaseStation.query.count(),
                    'mountpoints': MountPoint.query.count(),
                    'rovers': Rover.query.count(),
                    'active_bases': BaseStation.query.filter_by(status='connected').count(),
                    'active_rovers': sum(r.active_conn for r in Rover.query.all())
                }
                
                return jsonify({
                    'status': 'ok',
                    'timestamp': int(time.time()),
                    'system': system_info,
                    'resources': resources,
                    'database': db_stats
                })
            except Exception as e:
                logger.error(f"Error in api_status: {e}")
                return jsonify({'error': str(e)}), 500

        def _to_float_or_default(raw_value, default_value):
            try:
                if raw_value is None or raw_value == '':
                    return float(default_value)
                return float(raw_value)
            except (TypeError, ValueError):
                return float(default_value)

        def _to_int_or_default(raw_value, default_value):
            try:
                if raw_value is None or raw_value == '':
                    return int(default_value)
                return int(raw_value)
            except (TypeError, ValueError):
                return int(default_value)

        def _normalize_multiline_text(raw_value, field_name, max_length=4000):
            normalized = str(raw_value or '').replace('\r\n', '\n').replace('\r', '\n').strip()
            if len(normalized) > max_length:
                raise ValueError(f'{field_name} must be {max_length} characters or less')
            return normalized

        def parse_command_lines(raw_value):
            normalized = str(raw_value or '').replace('\r\n', '\n').replace('\r', '\n')
            result = []
            for line in normalized.split('\n'):
                cleaned = str(line or '').strip()
                if not cleaned or cleaned.startswith('#'):
                    continue
                result.append(cleaned)
            return result

        def _normalize_base_station_settings(data, partial=False):
            if not isinstance(data, dict):
                raise ValueError('Invalid settings payload')

            settings = {}

            requested_connection_type = str(
                data.get('connection_type', 'bluetooth')
            ).strip().lower()
            if requested_connection_type in ('usb', 'usb_serial'):
                requested_connection_type = 'serial'
            if requested_connection_type in ('bluetooth_le', 'bluetooth-le'):
                requested_connection_type = 'ble'

            if (not partial) or ('connection_type' in data):
                if requested_connection_type not in ('bluetooth', 'ble', 'serial'):
                    raise ValueError('connection_type must be bluetooth, ble or serial')
                settings['connection_type'] = requested_connection_type

            effective_connection_type = settings.get('connection_type') or requested_connection_type
            if not effective_connection_type:
                effective_connection_type = 'bluetooth'

            if (not partial) or ('gnss_port' in data):
                default_port = (
                    '/dev/rfcomm1'
                    if effective_connection_type == 'bluetooth'
                    else '/dev/ttyACM0'
                )
                gnss_port = str(data.get('gnss_port', default_port)).strip()
                if not gnss_port:
                    raise ValueError('gnss_port is required')
                if len(gnss_port) > 64:
                    raise ValueError('gnss_port is too long')
                settings['gnss_port'] = gnss_port

            if (not partial) or ('baudrate' in data):
                baudrate = _to_int_or_default(data.get('baudrate', 115200), 115200)
                if baudrate <= 0:
                    raise ValueError('baudrate must be greater than 0')
                settings['baudrate'] = baudrate

            if (not partial) or ('data_bits' in data):
                data_bits = _to_int_or_default(data.get('data_bits', 8), 8)
                if data_bits not in (7, 8):
                    raise ValueError('data_bits must be 7 or 8')
                settings['data_bits'] = data_bits

            if (not partial) or ('stop_bits' in data):
                stop_bits = _to_int_or_default(data.get('stop_bits', 1), 1)
                if stop_bits not in (1, 2):
                    raise ValueError('stop_bits must be 1 or 2')
                settings['stop_bits'] = stop_bits

            if (not partial) or ('parity' in data):
                parity = str(data.get('parity', 'N')).strip().upper()
                if parity not in ('N', 'E', 'O'):
                    raise ValueError('parity must be N, E, or O')
                settings['parity'] = parity

            if (not partial) or ('data_type' in data):
                data_type = str(data.get('data_type', 'RTCM3')).strip().upper()
                if data_type not in ('RTCM3', 'NMEA', 'BOTH'):
                    raise ValueError('data_type must be RTCM3, NMEA, or BOTH')
                settings['data_type'] = data_type

            if (not partial) or ('output_interval' in data):
                output_interval = _to_int_or_default(data.get('output_interval', 1), 1)
                if output_interval < 1 or output_interval > 60:
                    raise ValueError('output_interval must be between 1 and 60')
                settings['output_interval'] = output_interval

            if (not partial) or ('position_mode' in data):
                position_mode = str(data.get('position_mode', 'auto')).strip().lower()
                if position_mode not in ('auto', 'manual'):
                    raise ValueError('position_mode must be auto or manual')
                settings['position_mode'] = position_mode

            if (not partial) or ('position_accuracy' in data):
                position_accuracy = _to_float_or_default(data.get('position_accuracy', 1.0), 1.0)
                if position_accuracy <= 0:
                    raise ValueError('position_accuracy must be greater than 0')
                settings['position_accuracy'] = position_accuracy

            if (not partial) or ('manual_lat' in data):
                manual_lat = _to_float_or_default(data.get('manual_lat', 0.0), 0.0)
                if manual_lat < -90 or manual_lat > 90:
                    raise ValueError('manual_lat must be between -90 and 90')
                settings['manual_lat'] = manual_lat

            if (not partial) or ('manual_lon' in data):
                manual_lon = _to_float_or_default(data.get('manual_lon', 0.0), 0.0)
                if manual_lon < -180 or manual_lon > 180:
                    raise ValueError('manual_lon must be between -180 and 180')
                settings['manual_lon'] = manual_lon

            if (not partial) or ('manual_alt' in data):
                manual_alt = _to_float_or_default(data.get('manual_alt', 0.0), 0.0)
                settings['manual_alt'] = manual_alt

            if (not partial) or ('operation_mode' in data):
                operation_mode = str(data.get('operation_mode', 'base')).strip().lower()
                if operation_mode not in ('base', 'rover', 'moving_base'):
                    raise ValueError('operation_mode must be base, rover, or moving_base')
                settings['operation_mode'] = operation_mode

            if (not partial) or ('receiver_brand' in data):
                receiver_brand = str(data.get('receiver_brand', 'comnav') or 'comnav').strip().lower()
                if receiver_brand not in ('comnav', 'unicore', 'um980', 'ublox', 'generic_nmea'):
                    raise ValueError('receiver_brand must be comnav, unicore, ublox, or generic_nmea')
                settings['receiver_brand'] = receiver_brand

            if (not partial) or ('survey_duration_sec' in data):
                survey_duration_sec = _to_int_or_default(data.get('survey_duration_sec', 30), 30)
                if survey_duration_sec < 15 or survey_duration_sec > 300:
                    raise ValueError('survey_duration_sec must be between 15 and 300 seconds')
                settings['survey_duration_sec'] = survey_duration_sec

            if (not partial) or ('antenna_height' in data):
                antenna_height = _to_float_or_default(data.get('antenna_height', 0.0), 0.0)
                settings['antenna_height'] = antenna_height

            if (not partial) or ('add_antenna_height' in data):
                settings['add_antenna_height'] = bool(data.get('add_antenna_height', False))

            if (not partial) or ('antenna_type' in data):
                settings['antenna_type'] = str(data.get('antenna_type', '')).strip()[:128]

            if (not partial) or ('antenna_serial' in data):
                settings['antenna_serial'] = str(data.get('antenna_serial', '')).strip()[:128]

            if (not partial) or ('command_strategy' in data):
                command_strategy = str(
                    data.get('command_strategy', 'generated') or 'generated'
                ).strip().lower()
                if command_strategy not in ('generated', 'overrides', 'replace'):
                    raise ValueError('command_strategy must be generated, overrides, or replace')
                settings['command_strategy'] = command_strategy

            if (not partial) or ('startup_commands' in data):
                settings['startup_commands'] = _normalize_multiline_text(
                    data.get('startup_commands', ''),
                    'startup_commands'
                )

            if (not partial) or ('shutdown_commands' in data):
                settings['shutdown_commands'] = _normalize_multiline_text(
                    data.get('shutdown_commands', ''),
                    'shutdown_commands'
                )

            return settings

        def _compose_receiver_preview_payload(preview_station):
            from app.bluetooth.core import bluetooth_manager

            generated_defaults = bluetooth_manager.get_receiver_command_defaults(preview_station)
            generated_startup = str(generated_defaults.get('startup', '') or '').strip()
            generated_shutdown = str(generated_defaults.get('shutdown', '') or '').strip()

            command_strategy = str(
                getattr(preview_station, 'command_strategy', 'generated') or 'generated'
            ).strip().lower()
            if command_strategy not in ('generated', 'overrides', 'replace'):
                command_strategy = 'generated'

            raw_startup = str(getattr(preview_station, 'startup_commands', '') or '').strip()
            raw_shutdown = str(getattr(preview_station, 'shutdown_commands', '') or '').strip()
            receiver_brand = str(getattr(preview_station, 'receiver_brand', 'comnav') or 'comnav').strip().lower()

            parsed_generated_startup = parse_command_lines(generated_startup)
            parsed_generated_shutdown = parse_command_lines(generated_shutdown)
            parsed_raw_startup = parse_command_lines(raw_startup)
            parsed_raw_shutdown = parse_command_lines(raw_shutdown)

            if command_strategy == 'replace':
                effective_startup = parsed_raw_startup or parsed_generated_startup
                effective_shutdown = parsed_raw_shutdown or parsed_generated_shutdown
            elif command_strategy == 'overrides':
                effective_startup = parsed_generated_startup + parsed_raw_startup
                effective_shutdown = parsed_generated_shutdown + parsed_raw_shutdown
            else:
                effective_startup = parsed_generated_startup
                effective_shutdown = parsed_generated_shutdown

            preview_message = (
                'Generated commands are composed from global RTCM Settings, '
                'output interval, operation mode, and optional advanced overrides.'
            )
            if receiver_brand in ('unicore', 'um980'):
                preview_message = (
                    'Unicore UM980 (DIY-GNSS-MINI) uses the NovAtel-style command set '
                    '(mode base / rtcm10xx / unlog / saveconfig), generated automatically '
                    'from your RTCM settings and base position.'
                )
            elif receiver_brand == 'ublox':
                preview_message = (
                    'u-blox receivers require a dedicated backend command strategy. '
                    'Generated ASCII commands are intentionally empty; use expert mode '
                    'or implement the u-blox profile first.'
                )
            elif receiver_brand == 'generic_nmea':
                preview_message = (
                    'Generic NMEA receivers expose only safe NMEA output commands by default. '
                    'Receiver-specific configuration must be added as advanced overrides.'
                )

            return {
                'command_strategy': command_strategy,
                'generated_startup_commands': generated_startup,
                'generated_shutdown_commands': generated_shutdown,
                'effective_startup_commands': '\n'.join(effective_startup),
                'effective_shutdown_commands': '\n'.join(effective_shutdown),
                'startup_commands': '\n'.join(effective_startup),
                'shutdown_commands': '\n'.join(effective_shutdown),
                'raw_startup_commands': raw_startup,
                'raw_shutdown_commands': raw_shutdown,
                'managed_by_rtcm_settings': True,
                'message': preview_message,
            }

        def _build_named_receiver_profile_payload(profile_name, preview_station):
            normalized_profile = str(profile_name or '').strip().lower()
            profile_station = SimpleNamespace(**dict(preview_station.__dict__))

            if normalized_profile == 'generated_base':
                profile_station.operation_mode = 'base'
                profile_station.position_mode = 'auto'
                profile_station.command_strategy = 'generated'
            elif normalized_profile == 'manual_base':
                profile_station.operation_mode = 'base'
                profile_station.position_mode = 'manual'
                profile_station.command_strategy = 'generated'
            elif normalized_profile in ('rover', 'nmea_rover'):
                profile_station.operation_mode = 'rover'
                profile_station.position_mode = 'auto'
                profile_station.command_strategy = 'generated'
            elif normalized_profile == 'rtcm_msm':
                profile_station.operation_mode = 'base'
                profile_station.position_mode = 'auto'
                profile_station.command_strategy = 'generated'
            elif normalized_profile == 'safe_shutdown':
                payload = _compose_receiver_preview_payload(profile_station)
                payload['effective_startup_commands'] = ''
                payload['startup_commands'] = ''
                payload['effective_shutdown_commands'] = payload.get('generated_shutdown_commands', '')
                payload['shutdown_commands'] = payload.get('generated_shutdown_commands', '')
                payload['message'] = 'Safe shutdown profile loaded from backend defaults.'
                return payload
            else:
                return _compose_receiver_preview_payload(profile_station)

            payload = _compose_receiver_preview_payload(profile_station)
            payload['message'] = f'Backend profile {normalized_profile} loaded.'
            return payload

        @app.route('/api/base_stations/receiver_defaults', methods=['POST'])
        @login_required
        def api_base_station_receiver_defaults():
            try:
                data = request.json or {}

                operation_mode = str(data.get('operation_mode', 'base') or 'base').strip().lower()
                if operation_mode not in ('base', 'rover', 'moving_base'):
                    operation_mode = 'base'

                position_mode = str(data.get('position_mode', 'auto') or 'auto').strip().lower()
                if position_mode not in ('auto', 'manual'):
                    position_mode = 'auto'

                preview_station = SimpleNamespace(
                    output_interval=_to_int_or_default(data.get('output_interval', 1), 1),
                    operation_mode=operation_mode,
                    position_mode=position_mode,
                    manual_lat=_to_float_or_default(data.get('manual_lat', 0.0), 0.0),
                    manual_lon=_to_float_or_default(data.get('manual_lon', 0.0), 0.0),
                    manual_alt=_to_float_or_default(data.get('manual_alt', 0.0), 0.0),
                    receiver_brand=str(data.get('receiver_brand', 'comnav') or 'comnav'),
                    survey_duration_sec=_to_int_or_default(data.get('survey_duration_sec', 30), 30),
                    command_strategy=str(data.get('command_strategy', 'generated') or 'generated'),
                    startup_commands=str(data.get('startup_commands', '') or ''),
                    shutdown_commands=str(data.get('shutdown_commands', '') or ''),
                )
                requested_profile = str(data.get('profile', '') or '').strip()
                if requested_profile:
                    return jsonify(_build_named_receiver_profile_payload(requested_profile, preview_station))

                return jsonify(_compose_receiver_preview_payload(preview_station))
            except Exception as e:
                logger.error(f"Error generating receiver command defaults: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/base_stations/serial_ports')
        @login_required
        def api_base_station_serial_ports():
            try:
                ports = {}

                def add_port(device, label=None, description='', hardware_id='', by_id=''):
                    device = str(device or '').strip()
                    if not device:
                        return
                    ports[device] = {
                        'device': device,
                        'label': str(label or os.path.basename(device) or device),
                        'description': str(description or ''),
                        'hardware_id': str(hardware_id or ''),
                        'by_id': str(by_id or ''),
                        'exists': os.path.exists(device),
                    }

                try:
                    from serial.tools import list_ports
                    for port_info in list_ports.comports():
                        add_port(
                            port_info.device,
                            label=os.path.basename(port_info.device or ''),
                            description=port_info.description or '',
                            hardware_id=port_info.hwid or '',
                        )
                except Exception as serial_scan_error:
                    logger.debug(f'pyserial port scan unavailable: {serial_scan_error}')

                for pattern in ('/dev/ttyACM*', '/dev/ttyUSB*', '/dev/ttyAMA*', '/dev/ttyS*'):
                    for device in sorted(glob.glob(pattern)):
                        add_port(device)

                for link_path in sorted(glob.glob('/dev/serial/by-id/*')):
                    try:
                        target_path = os.path.realpath(link_path)
                    except Exception:
                        target_path = ''
                    if target_path:
                        add_port(
                            target_path,
                            label=os.path.basename(link_path),
                            description='USB serial device by-id symlink',
                            by_id=link_path,
                        )

                return jsonify({
                    'ports': sorted(
                        ports.values(),
                        key=lambda item: (
                            0 if item.get('by_id') else 1,
                            item.get('device', ''),
                        ),
                    )
                })
            except Exception as e:
                logger.error(f"Error listing serial ports: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/base_stations/<int:id>/command_test', methods=['POST'])
        @login_required
        def api_base_station_command_test(id):
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                station = BaseStation.query.get_or_404(id)
                data = request.json or {}
                phase = str(data.get('phase', 'manual') or 'manual').strip().lower()
                if phase not in ('startup', 'shutdown', 'manual'):
                    phase = 'manual'

                raw_commands = data.get('commands')
                if raw_commands is None:
                    raw_commands = data.get(f'{phase}_commands')
                if raw_commands is None:
                    raw_commands = data.get('startup_commands', '')

                if isinstance(raw_commands, list):
                    commands = [str(command or '').strip() for command in raw_commands]
                else:
                    commands = [
                        line.strip()
                        for line in str(raw_commands or '').replace('\r\n', '\n').replace('\r', '\n').split('\n')
                    ]

                commands = [
                    command for command in commands
                    if command and not command.startswith('#')
                ]
                if not commands:
                    return jsonify({'error': 'No receiver commands provided'}), 400
                if len(commands) > 50:
                    return jsonify({'error': 'At most 50 commands can be tested at once'}), 400
                if sum(len(command) for command in commands) > 4000:
                    return jsonify({'error': 'Receiver command test payload is too large'}), 400

                from app.bluetooth.core import bluetooth_manager

                success, message, sent_count, command_results = bluetooth_manager.send_receiver_commands_to_station(
                    station.id,
                    commands,
                    phase=f'test-{phase}',
                )

                status_code = 200 if success else 409
                return jsonify({
                    'success': success,
                    'message': message,
                    'sent_count': sent_count,
                    'results': command_results,
                    'station_id': station.id,
                    'station_name': station.name,
                    'phase': phase,
                }), status_code
            except Exception as e:
                logger.error(f"Error testing receiver commands: {e}")
                return jsonify({'error': str(e)}), 500

