        # ── Receiver config versioning helpers (Fix #17) ────────────────────
        # Fields that constitute the "receiver configuration" we snapshot.
        _CONFIG_FIELDS = [
            'connection_type', 'gnss_port', 'baudrate', 'data_bits', 'stop_bits',
            'parity', 'data_type', 'output_interval', 'position_mode',
            'position_accuracy', 'manual_lat', 'manual_lon', 'manual_alt',
            'operation_mode', 'receiver_brand', 'survey_duration_sec',
            'antenna_height', 'add_antenna_height', 'antenna_type', 'antenna_serial',
            'command_strategy', 'startup_commands', 'shutdown_commands',
        ]

        def _snapshot_station_config(station):
            """Return a JSON-serialisable dict of the station's config fields."""
            snap = {}
            for field in _CONFIG_FIELDS:
                value = getattr(station, field, None)
                snap[field] = value
            return snap

        def _config_changed(station, new_snapshot):
            """True if new_snapshot differs from the latest stored version."""
            latest = (
                ReceiverConfigVersion.query
                .filter_by(station_id=station.id)
                .order_by(ReceiverConfigVersion.version.desc())
                .first()
            )
            if not latest:
                return True
            try:
                previous = json.loads(latest.config_json or '{}')
            except Exception:
                return True
            return previous != new_snapshot

        def _record_config_version(station, source='edit', note='', force=False):
            """Write a new ReceiverConfigVersion if the config changed (or force).

            Returns the created version number, or None if unchanged.
            Must be called within an app context; caller commits.
            """
            snapshot = _snapshot_station_config(station)
            if not force and not _config_changed(station, snapshot):
                return None

            last = (
                ReceiverConfigVersion.query
                .filter_by(station_id=station.id)
                .order_by(ReceiverConfigVersion.version.desc())
                .first()
            )
            next_version = (last.version + 1) if last else 1

            try:
                author = getattr(current_user, 'username', '') or ''
            except Exception:
                author = ''

            version_row = ReceiverConfigVersion(
                station_id=station.id,
                version=next_version,
                config_json=json.dumps(snapshot, default=str),
                source=source,
                note=str(note or '')[:255],
                created_by=author,
            )
            db.session.add(version_row)

            # Cap history at 50 versions per station.
            excess = (
                ReceiverConfigVersion.query
                .filter_by(station_id=station.id)
                .count()
            ) - 50
            if excess > 0:
                old_ids = [
                    row.id for row in (
                        ReceiverConfigVersion.query
                        .filter_by(station_id=station.id)
                        .order_by(ReceiverConfigVersion.version.asc())
                        .limit(excess)
                        .all()
                    )
                ]
                if old_ids:
                    ReceiverConfigVersion.query.filter(
                        ReceiverConfigVersion.id.in_(old_ids)
                    ).delete(synchronize_session=False)

            return next_version

        @app.route('/api/base_stations/create', methods=['POST'])
        @login_required
        def api_create_base_station():
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                data = request.json or {}
                if not data or 'name' not in data:
                    return jsonify({'error': 'Missing required fields'}), 400

                station_name = str(data.get('name', '')).strip()
                if not station_name:
                    return jsonify({'error': 'Missing required fields'}), 400
                
                # Check if station already exists
                existing = BaseStation.query.filter_by(name=station_name).first()
                if existing:
                    return jsonify({'error': 'Base station with this name already exists'}), 400

                try:
                    settings_values = _normalize_base_station_settings(data, partial=False)
                except ValueError as validation_error:
                    return jsonify({'error': str(validation_error)}), 400

                connection_type = settings_values.get('connection_type', 'bluetooth')

                channel_value = _to_int_or_default(data.get('channel', 1), 1)
                if channel_value < 1 or channel_value > 30:
                    return jsonify({'error': 'Channel must be between 1 and 30'}), 400

                bt_mac = str(data.get('bt_mac', '')).strip().upper()
                if connection_type in ('bluetooth', 'ble'):
                    if not bt_mac:
                        return jsonify({'error': 'Bluetooth MAC is required for Bluetooth connection types'}), 400

                    mac_regex = r'^([0-9A-F]{2}[:-]){5}([0-9A-F]{2})$'
                    if not re.match(mac_regex, bt_mac):
                        return jsonify({'error': 'Invalid Bluetooth MAC format'}), 400

                    existing_mac = BaseStation.query.filter(
                        BaseStation.bt_mac == bt_mac
                    ).first()
                    if existing_mac:
                        return jsonify({'error': 'Base station with this MAC address already exists'}), 400

                if connection_type == 'bluetooth':
                    # Only classic RFCOMM occupies a channel and a /dev node;
                    # BLE talks over GATT and needs neither.
                    existing_channel_station = BaseStation.query.filter(
                        BaseStation.connection_type == 'bluetooth',
                        BaseStation.channel == channel_value
                    ).first()
                    if existing_channel_station:
                        return jsonify({'error': f'RFCOMM channel {channel_value} is already used by {existing_channel_station.name}'}), 409

                    settings_values['gnss_port'] = f'/dev/rfcomm{channel_value}'
                elif connection_type == 'ble':
                    settings_values['gnss_port'] = ''
                else:
                    bt_mac = ''
                
                station = BaseStation(
                    name=station_name,
                    bt_mac=bt_mac,
                    channel=channel_value,
                    status='disconnected',
                    **settings_values
                )
                
                db.session.add(station)
                db.session.commit()
                # Fix #17: record the initial config version.
                try:
                    _record_config_version(station, source='initial', note='Station created', force=True)
                    db.session.commit()
                except Exception as _ver_err:
                    db.session.rollback()
                    logger.warning(f"Could not record initial config version: {_ver_err}")
                return jsonify({'message': 'Base station created', 'id': station.id}), 201
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error creating base station: {e}")
                return jsonify({'error': str(e)}), 500
        
        @app.route('/api/base_stations/<int:id>/update', methods=['PUT'])
        @login_required
        def api_update_base_station(id):
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                station = BaseStation.query.get_or_404(id)
                data = request.json or {}
                
                if 'name' in data:
                    normalized_name = str(data.get('name', '')).strip()
                    if not normalized_name:
                        return jsonify({'error': 'Base station name cannot be empty'}), 400
                    # Check if name already exists (excluding current station)
                    existing = BaseStation.query.filter(
                        BaseStation.name == normalized_name,
                        BaseStation.id != id
                    ).first()
                    if existing:
                        return jsonify({'error': 'Base station with this name already exists'}), 400
                    station.name = normalized_name

                effective_connection_type = str(
                    data.get('connection_type', station.connection_type or 'bluetooth')
                ).strip().lower()
                if effective_connection_type in ('usb', 'usb_serial'):
                    effective_connection_type = 'serial'
                if effective_connection_type in ('bluetooth_le', 'bluetooth-le'):
                    effective_connection_type = 'ble'

                if effective_connection_type not in ('bluetooth', 'ble', 'serial'):
                    return jsonify({'error': 'connection_type must be bluetooth, ble or serial'}), 400

                if 'connection_type' in data:
                    station.connection_type = effective_connection_type

                if 'channel' in data:
                    channel_value = _to_int_or_default(data.get('channel', station.channel), station.channel)
                    if channel_value < 1 or channel_value > 30:
                        return jsonify({'error': 'Channel must be between 1 and 30'}), 400
                    station.channel = channel_value
                
                if 'status' in data:
                    station.status = data['status']

                normalized_mac = str(data.get('bt_mac', station.bt_mac or '')).strip().upper()
                if effective_connection_type in ('bluetooth', 'ble'):
                    if not normalized_mac:
                        return jsonify({'error': 'Bluetooth MAC is required for Bluetooth connection types'}), 400

                    mac_regex = r'^([0-9A-F]{2}[:-]){5}([0-9A-F]{2})$'
                    if not re.match(mac_regex, normalized_mac):
                        return jsonify({'error': 'Invalid Bluetooth MAC format'}), 400

                    existing_mac = BaseStation.query.filter(
                        BaseStation.bt_mac == normalized_mac,
                        BaseStation.id != id
                    ).first()
                    if existing_mac:
                        return jsonify({'error': 'Base station with this MAC address already exists'}), 400

                    if effective_connection_type == 'bluetooth':
                        existing_channel_station = BaseStation.query.filter(
                            BaseStation.connection_type == 'bluetooth',
                            BaseStation.channel == station.channel,
                            BaseStation.id != id
                        ).first()
                        if existing_channel_station:
                            return jsonify({'error': f'RFCOMM channel {station.channel} is already used by {existing_channel_station.name}'}), 409
                        station.gnss_port = f'/dev/rfcomm{station.channel}'
                    else:
                        # BLE talks over GATT: no RFCOMM channel, no /dev node.
                        station.gnss_port = ''

                    station.bt_mac = normalized_mac
                elif 'bt_mac' in data:
                    station.bt_mac = normalized_mac

                try:
                    settings_payload = dict(data)
                    settings_payload['connection_type'] = effective_connection_type
                    settings_values = _normalize_base_station_settings(settings_payload, partial=True)
                except ValueError as validation_error:
                    return jsonify({'error': str(validation_error)}), 400

                if effective_connection_type == 'bluetooth' and 'gnss_port' not in data:
                    settings_values['gnss_port'] = f'/dev/rfcomm{station.channel}'
                elif (
                    effective_connection_type == 'serial'
                    and 'connection_type' in data
                    and 'gnss_port' not in data
                ):
                    settings_values['gnss_port'] = '/dev/ttyACM0'

                for key, value in settings_values.items():
                    setattr(station, key, value)
                
                station.updated_at = int(time.time())
                db.session.commit()

                # Fix #17: snapshot config if any config-bearing field changed.
                try:
                    new_version = _record_config_version(station, source='edit')
                    if new_version:
                        db.session.commit()
                except Exception as _ver_err:
                    db.session.rollback()
                    logger.warning(f"Could not record config version: {_ver_err}")

                return jsonify({'message': 'Base station updated'}), 200
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error updating base station: {e}")
                return jsonify({'error': str(e)}), 500
        
