        def _parse_bool(value):
            if isinstance(value, bool):
                return value
            if isinstance(value, (int, float)):
                return value != 0
            if value is None:
                return False
            return str(value).strip().lower() in ('1', 'true', 'yes', 'on')

        def _normalize_rtcm_settings_map(settings_data):
            normalized = {}
            if not isinstance(settings_data, dict):
                return normalized

            for msg_type_raw, enabled_raw in settings_data.items():
                try:
                    msg_type = int(msg_type_raw)
                except (TypeError, ValueError):
                    continue
                normalized[str(msg_type)] = _parse_bool(enabled_raw)

            return normalized

        def _get_current_rtcm_settings_map():
            current = {}
            rows = RTCMSetting.query.all()
            for row in rows:
                current[str(row.msg_type)] = bool(row.enabled)
            return current

        def _load_rtcm_presets():
            setting = SystemSetting.query.filter_by(key='rtcm_presets').first()
            if not setting or not setting.value:
                return {}

            try:
                decoded = json.loads(setting.value)
                if isinstance(decoded, dict):
                    return decoded
            except Exception as e:
                logger.warning(f"Unable to decode RTCM presets from DB: {e}")

            return {}

        def _save_rtcm_presets(presets):
            setting = SystemSetting.query.filter_by(key='rtcm_presets').first()
            now_ts = int(time.time())
            serialized = json.dumps(presets, ensure_ascii=False)

            if setting:
                setting.value = serialized
                setting.updated_at = now_ts
                if not setting.description:
                    setting.description = 'Saved RTCM message presets'
                return

            db.session.add(SystemSetting(
                key='rtcm_presets',
                value=serialized,
                description='Saved RTCM message presets',
                created_at=now_ts,
                updated_at=now_ts,
            ))

        def _resolve_preset_settings(preset_entry):
            if not isinstance(preset_entry, dict):
                return {}

            # Backward/forward compatible shape:
            # 1) {"settings": {...}, "saved_at": ...}
            # 2) {...} (direct settings map)
            if 'settings' in preset_entry and isinstance(preset_entry.get('settings'), dict):
                return _normalize_rtcm_settings_map(preset_entry.get('settings'))

            return _normalize_rtcm_settings_map(preset_entry)

