        @app.route('/api/system/backups/storage')
        @login_required
        def api_system_backup_storage():
            """Where backups actually land, and whether that will survive.

            The dangerous failure mode is a backup nobody checks: it lives on
            the same card as the system, or the USB drive silently unmounted
            after a reboot. This reports both, plus free space.
            """
            import shutil

            def describe(path_value, label):
                entry = {
                    'label': label,
                    'path': path_value,
                    'configured': bool(path_value),
                    'exists': False,
                    'writable': False,
                    'device': '',
                    'free_bytes': 0,
                    'total_bytes': 0,
                }
                if not path_value:
                    return entry
                entry['exists'] = os.path.isdir(path_value)
                if not entry['exists']:
                    return entry
                entry['writable'] = os.access(path_value, os.W_OK)
                try:
                    usage = shutil.disk_usage(path_value)
                    entry['free_bytes'] = int(usage.free)
                    entry['total_bytes'] = int(usage.total)
                except OSError:
                    pass
                try:
                    entry['device'] = str(os.stat(path_value).st_dev)
                except OSError:
                    pass
                return entry

            try:
                # Same directory _list_backup_files() reads, so both agree.
                local_path = '/opt/gnss-caster/backups'
                external_path = str(
                    _get_system_setting_value('backup_external_path', '') or ''
                ).strip()

                local = describe(local_path, 'Primary (on this host)')
                external = describe(external_path, 'Second copy')

                warnings = []
                if not external['configured']:
                    warnings.append(
                        'No second copy configured: a card failure would take the backups with it.'
                    )
                elif not external['exists']:
                    warnings.append(
                        f'Second copy path "{external_path}" does not exist - is the drive mounted?'
                    )
                elif not external['writable']:
                    warnings.append(f'Second copy path "{external_path}" is not writable.')
                elif external['device'] and external['device'] == local['device']:
                    warnings.append(
                        'Second copy is on the same filesystem as the primary, '
                        'so it will not survive a card failure.'
                    )

                return jsonify({
                    'local': local,
                    'external': external,
                    'warnings': warnings,
                })
            except Exception as e:
                logger.error(f'Error getting backup storage information: {e}')
                return jsonify({'error': str(e)}), 500

        def _preview_backup_archive(filename, passphrase=''):
            import signal
            import sys
            safe_name, archive_path = _resolve_backup_archive_path(str(filename))
            if len(passphrase.encode('utf-8')) > 4096 or '\n' in passphrase or '\r' in passphrase:
                raise ValueError('Backup passphrase is invalid')
            if not _backup_preview_slots.acquire(blocking=False):
                raise ValueError('Another backup inspection is running. Try again shortly.')
            try:
                script = os.path.join(os.path.dirname(os.path.dirname(__file__)), 'backup_format.py')
                version_file = os.path.join(os.path.dirname(script), 'version.py')
                database = str(db.engine.url.database or '')
                proc = subprocess.Popen([sys.executable, '-I', script, 'preview', archive_path, database, version_file],
                                        stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                                        text=True, start_new_session=True)
                try:
                    output, _ = proc.communicate(passphrase, timeout=240)
                except subprocess.TimeoutExpired:
                    os.killpg(proc.pid, signal.SIGKILL)
                    proc.communicate()
                    raise ValueError('Backup inspection timed out')
                try:
                    result = json.loads(output)
                except (ValueError, TypeError):
                    raise ValueError('Backup inspection failed; the archive was not applied')
                if proc.returncode or result.get('error'):
                    raise ValueError(result.get('error') or 'Backup inspection failed; the archive was not applied')
                return dict(result, filename=safe_name)
            finally:
                _backup_preview_slots.release()

